/* Systems Atlas — curriculum data: Levels 0–3 (foundations, API engineering, thinking at scale, distributed systems)
   plus the comparison cards owned by this file. Content only; rendering lives in views.js. */
(function () {
  'use strict';

  /* concept section shorthand */
  const C = (id, title, plain, technical, tags, pitfall) =>
    ({ kind: 'concept', id, title, plain, technical, tags: tags || [], pitfall });
  const W = (widget, title, caption) => ({ kind: 'widget', widget, title, caption });
  const CMP = (id) => ({ kind: 'compare', id });
  const NOTE = (tone, text) => ({ kind: 'note', tone, text });

  /* =====================================================================
     Comparisons ("Why this, not that?")
     ===================================================================== */
  ACAD.addComparisons([
    {
      id: 'cmp-async-sync',
      title: 'Why asynchronous I/O instead of synchronous I/O?',
      a: 'Asynchronous (non-blocking) I/O', b: 'Synchronous (blocking) I/O',
      problem: `A backend spends most of each request <b>waiting</b>: for the database, a vector index, or an LLM that takes seconds. The question is what the server does with its workers while they wait.`,
      howA: `A small number of threads run an [[event-loop]]. When a request starts an I/O call, the handler registers interest and yields; the loop serves other requests until the OS signals that the response has arrived. One thread can keep thousands of requests in flight.`,
      howB: `Each request occupies one thread (or process) from start to finish. When the code calls the database, the thread sleeps until the reply arrives. Concurrency equals the number of threads in the pool.`,
      advA: `Very high in-flight concurrency per replica for I/O-bound work; low memory per waiting request (no thread stack); natural fit for streaming tokens and fan-out calls in parallel.`,
      advB: `Simpler mental model and stack traces; a CPU-heavy or accidentally blocking call only stalls its own thread; mature libraries everywhere; easier to reason about per-request state.`,
      latency: `Async does not make a single call faster. It prevents <b>queueing</b>: under load, requests stop waiting for a free thread, so p95/p99 stay closer to the actual downstream time. One blocking call inside an async handler, however, freezes every request on that loop.`,
      cost: `Async usually needs fewer replicas for the same I/O-bound traffic, because each replica holds more waiting requests. Engineering cost is higher: every library on the hot path must be non-blocking.`,
      scale: `Async scales in-flight requests per replica by orders of magnitude for I/O-bound loads. Neither model scales CPU-bound work beyond the number of cores; that needs more processes or more replicas.`,
      failure: `Async: a single blocking call or CPU-heavy step stalls the whole loop (latency spikes for everyone while CPU looks modest). Sync: [[thread]] pool exhaustion — all threads blocked on a slow dependency, new requests queue, CPU stays low.`,
      security: `Neither is inherently more secure. Async servers accept more concurrent connections, so explicit limits (max in-flight, timeouts, request size caps) matter more to resist slow-client and resource-exhaustion attacks.`,
      chooseA: `Most time is spent waiting on network calls (databases, search, LLM APIs), you stream responses, or you fan out to several services per request.`,
      chooseB: `Work is CPU-bound, traffic is modest, the team or libraries are synchronous, or the extra complexity buys nothing measurable.`,
      changes: `If profiling shows requests are CPU-bound (e.g. heavy parsing or local model inference), async alone will not help — you need more cores/processes. If a key dependency only has a blocking client, you must isolate it in a thread pool or choose sync.`,
      interview: `“Our chatbot requests spend over 90% of their time waiting on the vector index and the LLM. With synchronous workers, every waiting request pins a thread, so we hit thread-pool exhaustion while CPU sits at 20%. Async I/O lets one replica keep thousands of waits in flight. The trade-off is discipline: a single blocking call stalls the loop, so we lint for it, offload CPU work to a separate pool, and still bound concurrency so we don’t just move the queue downstream.”`,
    },
    {
      id: 'cmp-horizontal-vertical',
      title: 'Why horizontal scaling instead of vertical scaling?',
      a: 'Horizontal scaling (more replicas)', b: 'Vertical scaling (bigger machine)',
      problem: `A service can no longer keep up with its load. You can add <b>more copies</b> of it, or give the one copy <b>more CPU and memory</b>.`,
      howA: `Run N identical [[stateless]] replicas behind a [[load-balancer]]. Each handles a share of requests. [[autoscaling|Autoscaling]] adds or removes replicas from a metric such as CPU, concurrency, or queue length.`,
      howB: `Move the service to a larger instance (more cores, more RAM, faster disk). Same process, same code, more resources.`,
      advA: `No single-machine ceiling; tolerates the loss of a replica; scales in small increments; can scale back down; rolling deployments without downtime.`,
      advB: `Zero architectural change; no coordination between nodes; best for stateful systems that are hard to split (a primary database); lower latency for work that benefits from shared memory.`,
      latency: `Horizontal scaling reduces queueing only if the bottleneck is the service itself. Vertical scaling can reduce per-request latency for CPU-bound work (faster cores) but does not help if requests wait on a downstream dependency.`,
      cost: `Horizontal adds load balancer and per-replica overhead but tracks demand closely. Vertical has step-function pricing, often wastes capacity off-peak, and the largest instances cost disproportionately more.`,
      scale: `Horizontal has a much higher ceiling — until a <b>shared</b> dependency saturates (database connections, an LLM quota, a lock). Vertical hits a hard ceiling at the largest available machine.`,
      failure: `Horizontal: more replicas can overwhelm a shared database (connection-pool exhaustion) and add cold-start delay during spikes. Vertical: one machine is one failure domain; resizing often needs a restart.`,
      security: `Horizontal increases the number of instances to patch and secure, but each is disposable. Vertical concentrates risk in one host. Secrets distribution ([[managed-identity]], [[key-vault]]) matters more with many replicas.`,
      chooseA: `Stateless API tiers, workers, and anything that must survive instance failure or handle spiky traffic.`,
      chooseB: `Stateful components that are expensive to distribute (a relational primary), short-term relief while you fix an architecture, or CPU/memory-bound single-node workloads.`,
      changes: `If the real bottleneck is downstream (database, LLM rate limit), neither option helps — you must remove that bottleneck. If the state can be partitioned cleanly, horizontal becomes viable even for stateful parts.`,
      interview: `“I default to horizontal scaling for stateless tiers because it raises the ceiling and gives redundancy, but I first confirm the service itself is the bottleneck. If replicas share a database or an LLM quota, adding replicas just moves the queue — or makes things worse by exhausting connections. For the stateful core I often scale vertically first and partition only when measurements justify it.”`,
    },
    {
      id: 'cmp-monolith-microservices',
      title: 'Why a modular monolith instead of microservices (or the reverse)?',
      a: 'Modular monolith', b: 'Microservices',
      problem: `As a product grows, code, teams, and load grow too. You must decide where the deployment and ownership boundaries go.`,
      howA: `One deployable unit containing well-separated modules with clear internal interfaces. Calls between modules are in-process function calls. One database (possibly with schemas per module).`,
      howB: `Many independently deployable services, each owning its data and exposing an API. Calls between services cross the network.`,
      advA: `Simple to build, test, deploy, and debug; no network hops between modules; transactions are local; easy refactoring; fewer moving parts to monitor.`,
      advB: `Teams deploy independently; each service scales and fails independently; different services can use different data stores and runtimes; blast radius of a bad deploy is smaller.`,
      latency: `Monolith: in-process calls take microseconds. Microservices: each hop adds network latency, serialization, and the risk of tail latency compounding across a call chain.`,
      cost: `Monolith: cheapest to operate early. Microservices: more infrastructure, CI/CD pipelines, observability tooling, and platform engineering — justified only when organizational scale demands it.`,
      scale: `A monolith scales horizontally as a whole (often fine). Microservices let you scale only the hot component — useful when parts have very different load profiles (e.g. a CPU-heavy ingestion pipeline vs a light API).`,
      failure: `Monolith: one memory leak or bad deploy can take down everything. Microservices: partial failures, [[retry-storm|retry storms]], cascading timeouts, distributed transactions and data consistency problems.`,
      security: `Microservices add many network boundaries that each need authentication (service identity, mTLS or tokens) — more surface, but also finer-grained [[least-privilege]]. A monolith has fewer boundaries but coarser isolation.`,
      chooseA: `Small to medium teams, a new product, unclear domain boundaries, or a need to move fast.`,
      chooseB: `Many teams blocking each other on releases, components with very different scaling or reliability needs, or clearly stable domain boundaries.`,
      changes: `Team count and release contention are the strongest triggers. A single component with radically different scaling needs (e.g. document ingestion) can be split out on its own without going “full microservices”.`,
      interview: `“Microservices are an organizational scaling tool first. I’d start with a modular monolith with strict module boundaries, and extract a service only when there is a concrete reason — independent scaling, a different failure domain, or teams blocked on each other. Every extraction trades in-process calls for network calls, so I budget for timeouts, retries with idempotency, tracing, and eventual consistency.”`,
    },
    {
      id: 'cmp-queue-immediate',
      title: 'Why put work on a queue instead of processing it immediately?',
      a: 'Queue + background workers', b: 'Process inline in the request',
      problem: `Some work is slow, bursty, or does not need to finish before the user gets a response — document ingestion, emails, payment reconciliation, re-embedding a corpus.`,
      howA: `The API validates the request, writes a message to a [[message-queue]], returns <span class="mono">202 Accepted</span> with a job ID, and workers pull messages at their own pace. The client polls or is notified when done.`,
      howB: `The API performs all work before responding. The client waits on the open connection for the full result.`,
      advA: `Absorbs spikes (load leveling); workers scale independently; failures retry without the user waiting; producers are decoupled from consumer speed; failed messages land in a [[dead-letter-queue]] for inspection.`,
      advB: `Simplest design; the user gets the final result in one round trip; no job state to manage; no eventual consistency.`,
      latency: `Queues add end-to-end delay (time in queue) but make API response time short and predictable. Inline processing gives the lowest total latency at low load but tail latency explodes when load exceeds capacity.`,
      cost: `Queues let you run workers near average load instead of peak, and use cheaper batch capacity. They add a broker and job-tracking state.`,
      scale: `Queue-based load leveling scales smoothly if workers can eventually catch up. If arrival rate stays above worker throughput, the backlog grows without bound — a queue only buys time.`,
      failure: `Queues introduce duplicates ([[at-least-once]] delivery), poison messages, and backlog growth. Inline processing ties failures to user requests, causing timeouts and retries that amplify load.`,
      security: `Messages may contain sensitive data at rest in the broker; encrypt, restrict access with [[managed-identity]], and carry tenant identity in the message so workers enforce authorization.`,
      chooseA: `Work takes longer than a user should wait, arrives in bursts, can be retried, or must survive a crash midway.`,
      chooseB: `The user needs the answer now (a chat reply, a price lookup), the work is fast, and load is within capacity.`,
      changes: `If the user must see the result synchronously (a chatbot answer), a queue becomes a capacity buffer with bounded depth and a timeout rather than fire-and-forget. If workers can never catch up, you need more capacity or [[load-shedding]], not a bigger queue.`,
      interview: `“I queue work that is slow, bursty, or retryable — ingestion, re-embedding, notifications — and return 202 with a job ID. That decouples API latency from worker speed and lets workers scale on queue depth. But a queue is not capacity: if arrivals exceed throughput, depth grows forever, so I bound it, alert on queue age, and make consumers idempotent because delivery is at-least-once.”`,
    },
    {
      id: 'cmp-sse-websocket',
      title: 'Why Server-Sent Events instead of WebSockets (or polling)?',
      a: 'Server-Sent Events (SSE)', b: 'WebSockets',
      problem: `A chatbot streams an LLM answer token by token, or a dashboard pushes live updates. The client must receive data as it is produced instead of waiting for one large response.`,
      howA: `The client makes one ordinary HTTP request; the server keeps the response open and writes a stream of text events. One direction only: server to client. Browsers reconnect automatically and can resume with a last-event ID.`,
      howB: `The client upgrades an HTTP connection to a persistent, full-duplex socket. Either side can send messages at any time.`,
      advA: `Plain HTTP, so it passes through gateways, proxies, and CDNs that understand HTTP; works with standard auth headers/cookies; automatic reconnection; ideal for token streaming. Over HTTP/2 many streams share one connection.`,
      advB: `True bidirectional, low-overhead messaging; good for collaborative editing, games, voice, or interactive agents where the client sends frequent messages mid-stream.`,
      latency: `Both push data with minimal delay once connected. Polling adds up to one polling interval of delay and wastes requests when nothing changed.`,
      cost: `Both hold a connection per active client, so servers need high connection capacity (async I/O). WebSockets usually need sticky routing and gateway support for upgrades. Polling costs many empty requests.`,
      scale: `SSE scales like long-lived HTTP responses. WebSockets require connection-aware load balancing and often a pub/sub layer to fan messages to the replica holding each socket.`,
      failure: `SSE: intermediaries that buffer responses can break streaming (disable buffering). WebSockets: dropped connections need client-side reconnection and resume logic; stateful connections complicate deploys (draining).`,
      security: `SSE reuses normal HTTP auth and gateway policies. WebSockets need authentication at upgrade time, origin checks, and per-message authorization if the client can send commands.`,
      chooseA: `Server-to-client streaming such as LLM token streams, progress updates, notifications.`,
      chooseB: `Frequent bidirectional messages: real-time collaboration, live voice, multiplayer, agents that accept mid-stream interruptions.`,
      changes: `If the client needs to cancel or steer a generation mid-stream frequently, WebSockets become attractive (though a separate cancel request often suffices). If updates are rare and freshness tolerance is minutes, plain polling is simplest.`,
      interview: `“For LLM token streaming I’d choose SSE: it’s one-directional, plain HTTP, works through API gateways, carries normal auth, and reconnects automatically. WebSockets earn their extra complexity — sticky routing, upgrade support, connection draining — only when the client needs to send frequent messages during the stream. Either way I watch time-to-first-token and make sure no proxy buffers the response.”`,
    },
    {
      id: 'cmp-strong-eventual',
      title: 'Why strong consistency instead of eventual consistency?',
      a: 'Strong consistency', b: 'Eventual consistency',
      problem: `Data is replicated for availability and read scale. After a write, should every reader immediately see it, or may some readers briefly see older data?`,
      howA: `A write is acknowledged only after it is durable on enough replicas (or a single leader) that every subsequent read observes it. Reads go to the leader or use a [[quorum]] that overlaps the write.`,
      howB: `A write is acknowledged by one replica and propagated asynchronously. Replicas converge if writes stop, but a read may return stale data for a short window ([[replication-lag]]).`,
      advA: `Simple correctness: no stale reads, no lost updates when combined with transactions. Essential for inventory counts, balances, seat allocation, permissions.`,
      advB: `Lower write latency, higher availability during network partitions, reads served from the nearest replica, easy geographic scale.`,
      latency: `Strong consistency adds coordination latency — at least one round trip to a leader or quorum, which across regions is tens to hundreds of milliseconds. Eventual consistency reads locally.`,
      cost: `Strongly consistent multi-region systems need more replicas and expensive cross-region coordination. Eventual consistency is cheaper to scale reads.`,
      scale: `Strong consistency limits write throughput to what the coordination path can sustain. Eventual consistency scales reads and writes more easily but pushes conflict handling to the application.`,
      failure: `Strong: during a partition, the minority side must refuse writes (lower availability). Eventual: stale reads (user doesn’t see their own update), conflicting concurrent writes, overselling if used for inventory.`,
      security: `Stale permission data is a real risk: a revoked user may keep access until replicas converge. Authorization decisions usually need fresh data or short, bounded staleness.`,
      chooseA: `Money, inventory, bookings, unique constraints, access-control changes — anywhere a stale read causes an incorrect irreversible action.`,
      chooseB: `Feeds, view counts, recommendations, product catalog reads, analytics — where briefly stale data is acceptable.`,
      changes: `If the business tolerates a bounded window (e.g. “seat count may be 2 s stale on the browse page, but the reservation itself is atomic”), you can mix: eventual for display, strong for the decision.`,
      interview: `“I choose per operation, not per system. The seat reservation must be strongly consistent — an atomic conditional update on the authoritative record — because overselling is irreversible. The seat-availability display can be eventually consistent from a cache or replica, as long as the final booking step re-checks. I’d also make sure users read their own writes, e.g. by routing them to the leader right after an update.”`,
    },
    {
      id: 'cmp-kafka-servicebus',
      title: 'Why Kafka (an event stream) instead of Azure Service Bus (a message broker)?',
      a: 'Kafka / Event Hubs (event stream)', b: 'Azure Service Bus (message queue/broker)',
      problem: `Services need to communicate asynchronously. Sometimes you need a durable log of events that many consumers replay; sometimes you need reliable delivery of individual commands to one worker.`,
      howA: `An append-only, partitioned log. Producers append events; each consumer group tracks its own offset per partition and can rewind to replay. Messages stay for a retention period whether or not they are consumed. Ordering is per partition.`,
      howB: `A broker holds messages in queues or topic subscriptions. A consumer receives a message under a lock, processes it, and completes (deletes) it. Features include sessions for ordered processing, duplicate detection, scheduled delivery, dead-lettering, and transactions within the broker.`,
      advA: `Very high throughput; replayable history; many independent consumers read the same data; good for event-driven architecture, CDC, analytics, and stream processing.`,
      advB: `Per-message semantics: locks, retries with delivery counts, dead-letter queues, sessions, scheduled messages; easy competing-consumer work queues; rich enterprise messaging features.`,
      latency: `Both offer low milliseconds-to-tens-of-milliseconds delivery in normal operation; streams favor batching for throughput, brokers favor per-message handling.`,
      cost: `Streams are cost-efficient at very high volume. Brokers are cost-efficient for moderate volumes of business commands. Self-managed Kafka has high operational cost; managed offerings (Event Hubs with its Kafka-compatible endpoint, or managed Kafka services) reduce it.`,
      scale: `Stream throughput scales with partitions, but parallelism per consumer group is capped by partition count and hot partition keys create skew. Broker throughput depends on tier and entity design.`,
      failure: `Streams: a slow consumer falls behind (lag) but does not block others; a poison event blocks its partition unless skipped. Broker: poison messages move to the DLQ after max delivery attempts; lock expiry during slow processing causes redelivery (duplicates).`,
      security: `Both support managed identity and network isolation on Azure. Retention in streams means sensitive data persists for the retention window — plan PII handling accordingly.`,
      chooseA: `Event fan-out to many consumers, replay, audit/history, telemetry, CDC pipelines, very high event volumes.`,
      chooseB: `Commands and workflows (“process this order”), work distribution among competing consumers, ordered processing per session, dead-lettering and scheduled retries.`,
      changes: `If you need to rebuild a read model or onboard a new consumer from history, you want a log. If each message is a unit of work requiring individual retry and DLQ handling, a broker fits better. Many systems use both.`,
      interview: `“I separate events from commands. Facts like ‘OrderPlaced’ go to a partitioned log such as Event Hubs or Kafka so analytics, search indexing and notifications can each consume and replay independently. Work items like ‘charge this payment’ go to Service Bus, where I get per-message locks, delivery counts, dead-lettering and sessions. In both cases I assume at-least-once delivery and make consumers idempotent.”`,
    },
    {
      id: 'cmp-cdn-origin',
      title: 'Why a CDN instead of serving all media from the application?',
      a: 'CDN / edge caching', b: 'Serving from the origin application',
      problem: `Millions of viewers request the same video segments, images, and scripts. Serving every byte from your own servers concentrates bandwidth, connections, and latency in one place.`,
      howA: `Content is cached at many edge locations close to users. A viewer’s request is answered by a nearby edge if the object is cached ([[cache-hit-ratio|cache hit]]); on a miss, the edge fetches from the [[origin]] once and serves all subsequent viewers.`,
      howB: `Every client request travels to your application servers, which read the file (or generate it) and send the bytes back.`,
      advA: `Origin load drops by the cache hit ratio; latency drops because data travels a shorter distance; bandwidth is spread across a global network; absorbs flash crowds; edge features like TLS termination and DDoS protection.`,
      advB: `Total control and immediate freshness; simple for small, private, or highly personalized content; no cache invalidation problem.`,
      latency: `Edge hits are typically far faster than round trips to a distant origin. Misses add one extra hop. For live video, segment duration and cache TTL determine how fresh the edge is.`,
      cost: `CDN egress is generally cheaper at scale than origin egress and needs far less origin compute. Origin-only serving requires provisioning bandwidth and servers for peak.`,
      scale: `Origin request rate ≈ total request rate × (1 − hit ratio) — and with request collapsing, misses for the same object are merged into one origin fetch. At a 99% hit ratio, origin sees roughly 1% of requests.`,
      failure: `Cache stampede when a popular object expires; an edge region outage shifts traffic to other regions; bad cache keys serving one user’s content to another; purge storms.`,
      security: `Never cache personalized or authenticated responses under a shared key. Use signed URLs/tokens for paid content. The CDN can also absorb volumetric attacks before they reach the origin.`,
      chooseA: `Static or shared content (video segments, images, JS bundles, public API responses that are identical for many users), global audiences, flash crowds.`,
      chooseB: `Per-user, authenticated, rapidly changing, or low-volume content where caching gives little benefit or risks leaking data.`,
      changes: `If content is unique per viewer (personalized), hit ratio collapses and the CDN mostly acts as a TLS/DDoS edge. If freshness must be instant, you need short TTLs, purges, or bypass for that path.`,
      interview: `“Video bytes never go through the application API. Players fetch segments from the CDN, so origin load is total requests times the miss ratio, further reduced by request collapsing. The application only handles low-volume control traffic: login, entitlement, playback manifests. I’d monitor hit ratio and origin egress, shield the origin with a mid-tier cache, and keep personalized responses out of shared cache keys.”`,
    },
  ]);

  /* shared anatomy for the request journey and API modules */
  const API_ANATOMY_NODES = [
    { id: 'browser', label: 'Browser / app', kind: 'client', col: 0, row: 1,
      what: 'The program the user interacts with. It renders UI and sends HTTP requests.',
      why: 'It is the frontend: it decides what to ask for and how to show the answer.',
      out: 'HTTPS requests with headers, cookies or bearer tokens, and JSON bodies.',
      in: 'HTTP responses: status code, headers, JSON or HTML.',
      fails: 'Bad network, expired token, retries that duplicate a request.' },
    { id: 'dns', label: 'DNS resolver', kind: 'external', col: 1, row: 0,
      what: 'A directory that turns a name like api.example.com into an IP address.',
      why: 'Humans use names; networks route to addresses. DNS also lets operators move services without changing names.',
      in: 'A query for a hostname.', out: 'One or more IP addresses with a TTL (how long to cache).',
      fails: 'Outage or misconfiguration makes a healthy service unreachable; long TTLs slow failover.',
      monitor: 'Resolution latency and error rate; synthetic checks from several regions.' },
    { id: 'edge', label: 'CDN / Front Door', kind: 'edge', col: 1, row: 1,
      what: 'A globally distributed entry point that terminates TLS close to users and can cache responses.',
      why: 'Shortens the distance for the expensive handshakes and absorbs traffic before it reaches your servers.',
      fails: 'Caching a personalized response under a shared key; misrouted traffic during a regional failure.',
      alternatives: 'Direct regional entry (simpler, slower for distant users).' },
    { id: 'gw', label: 'API gateway', kind: 'gateway', col: 2, row: 1,
      what: 'A policy enforcement point for APIs: auth validation, rate limits, quotas, routing, transformation.',
      why: 'Keeps cross-cutting concerns out of every service and protects backends from abuse.',
      fails: 'Becomes a bottleneck or single point of failure if under-provisioned; overly broad policies block legitimate traffic.',
      scales: 'Scale units/instances; keep policies cheap.', monitor: 'Request rate, 4xx/5xx by API, policy latency, throttled count.' },
    { id: 'api', label: 'Backend API', kind: 'service', col: 3, row: 1,
      what: 'Your application code: validates input, applies business rules, calls data stores, builds the response.',
      why: 'The backend owns the data and the rules; the client cannot be trusted with either.',
      in: 'Validated HTTP request.', out: 'HTTP response; queries to the database.',
      fails: 'Thread or connection pool exhaustion, slow dependencies, memory leaks.',
      scales: 'Horizontally when stateless.', monitor: 'Latency percentiles, error rate, in-flight requests, saturation of pools.' },
    { id: 'db', label: 'Database', kind: 'db', col: 4, row: 1,
      what: 'Durable storage that answers queries and enforces constraints.',
      why: 'State must survive restarts and be shared across replicas.',
      stores: 'Rows/documents, indexes, transaction log.', fails: 'Slow queries, lock contention, connection limits, replication lag.',
      monitor: 'Query latency, active connections, lock waits, CPU/IO.' },
  ];

  /* =====================================================================
     Modules
     ===================================================================== */
  ACAD.addModules([
    /* ---------------------------------------------------------------- L0 */
    {
      id: 'l0-url-journey', level: 0, minutes: 25,
      title: 'What happens when you enter a URL',
      summary: 'Follow one request from the address bar through DNS, TCP, TLS and HTTP to a server and back, and see where the time goes.',
      prereqs: [],
      outcomes: [
        'You can narrate every network step between typing a URL and seeing a page.',
        'You can explain why the first request to a site is slower than later ones.',
        'You can say what HTTPS protects and what it does not.',
        'You can point to where caching, CDNs and connection reuse remove latency.',
      ],
      sections: [
        C('url-parts', 'A URL is an address with parts',
          `A URL like <span class="mono">https://api.example.com/properties/A?include=lease</span> tells the browser <b>how</b> to talk (https), <b>who</b> to talk to (api.example.com), <b>what</b> to ask for (/properties/A) and <b>extra details</b> (?include=lease).`,
          `Components: scheme, host, optional port (443 is the default for HTTPS), path, query string, and fragment (#section — never sent to the server). The host must become an IP address before any connection can be opened; the path and query travel inside the encrypted [[http]] request.`,
          ['http', 'https']),
        C('dns', 'DNS: turning a name into an address',
          `Computers route traffic to numeric IP addresses. [[dns|DNS]] is the internet’s phone book: you ask “where is api.example.com?” and get back an address.`,
          `The browser checks its own cache, then the OS, then a <b>recursive resolver</b> (your ISP, company, or a public resolver). On a miss, the resolver walks the hierarchy: root servers → the <span class="mono">.com</span> TLD servers → the domain’s authoritative name servers. Every answer has a TTL that controls how long it may be cached. DNS is also a traffic-steering tool: services return different addresses by geography or health (used by global load balancers).`,
          ['dns'],
          `Long TTLs make failover slow: clients keep using the old address until the cached record expires. Very short TTLs increase DNS load and lookup latency.`),
        C('tcp', 'TCP: a reliable pipe',
          `Before sending data, client and server agree to talk. [[tcp|TCP]] makes sure bytes arrive complete and in order, resending anything lost.`,
          `The three-way handshake (SYN, SYN-ACK, ACK) costs one network round trip (RTT) before data flows. TCP then provides ordering, retransmission, flow control (don’t overrun the receiver) and congestion control (don’t overrun the network). On a 80 ms RTT link, the handshake alone is 80 ms — which is why connection reuse matters so much.`,
          ['tcp', 'latency']),
        C('tls', 'TLS: privacy and identity',
          `[[tls|TLS]] wraps the connection in encryption and proves you are really talking to api.example.com, not an impostor.`,
          `During the TLS handshake the server presents a certificate chain signed by a trusted certificate authority; the client checks the name and validity, and both sides agree on session keys (forward-secret key exchange). TLS 1.3 needs one round trip for a fresh handshake (TLS 1.2 needed two), and resumption can reduce that further. After the handshake every byte is encrypted and integrity-protected.`,
          ['tls', 'https']),
        C('http', 'HTTP: the request and the response',
          `Once the pipe is ready, the browser sends a short message: “GET me /properties/A”. The server answers with a status code (did it work?), headers (metadata) and a body (the data).`,
          `A request has a method (GET, POST…), path, [[headers]] (Host, Authorization, Accept, Content-Type), and optionally a body. A response has a [[status-codes|status code]], headers (Content-Type, Cache-Control, ETag) and a body. HTTP/1.1 processes one request at a time per connection; HTTP/2 multiplexes many streams over one TCP connection; HTTP/3 runs over QUIC on UDP, which combines transport and TLS handshakes and avoids TCP head-of-line blocking when packets are lost.`,
          ['http', 'headers', 'status-codes']),
        C('https', 'HTTPS: what it does and does not protect',
          `[[https|HTTPS]] is HTTP inside TLS. Eavesdroppers on the network cannot read or change your requests.`,
          `HTTPS protects content, headers, path and query string in transit. It does <b>not</b> hide which server IP you connect to, it does not make the server trustworthy, and it does nothing once data reaches the server (logs, databases). Authentication of the <i>user</i> is a separate step — usually a token in the Authorization header.`,
          ['https', 'authentication'],
          `Query strings are encrypted in transit but often written to server and proxy logs. Never put secrets or tokens in URLs.`),
        W('url-journey', 'Experiment: where does the first request spend its time?',
          'Change the round-trip time and toggle connection reuse, DNS caching and a nearby CDN edge. Notice that on a cold first request most of the time goes to handshakes, not to the server doing work.'),
        {
          kind: 'steps', title: 'The full lifecycle of one HTTPS request',
          steps: [
            { title: 'Parse the URL', text: 'Browser extracts scheme, host, path, query. Checks its HTTP cache — a fresh cached response may avoid the network entirely.' },
            { title: 'Resolve the name', text: 'DNS lookup through caches and resolvers returns an IP address (often of a CDN or global entry point, not your server).' },
            { title: 'Open TCP', text: 'Three-way handshake: one RTT. Skipped if a pooled connection to the same host is open.' },
            { title: 'Negotiate TLS', text: 'Certificate check and key agreement: one RTT with TLS 1.3. Skipped when the connection is reused.' },
            { title: 'Send the HTTP request', text: 'Method, path, headers (including the auth token) and body are sent encrypted.' },
            { title: 'Edge and gateway', text: 'A CDN or global entry point may answer from cache. Otherwise it forwards to an API gateway that checks auth and rate limits.' },
            { title: 'Server work', text: 'The backend validates input, queries databases or other services, and builds a response. This is often the only part developers optimize.' },
            { title: 'Response travels back', text: 'Status, headers and body return. Large bodies may be compressed and streamed.' },
            { title: 'Render and reuse', text: 'The browser renders the result and keeps the connection open for the next request (keep-alive), so later requests skip DNS, TCP and TLS.' },
          ],
        },
        C('edge-and-cache', 'Caches along the way',
          `The fastest request is one that never reaches your server. Browsers, CDNs and gateways can keep copies of responses.`,
          `[[http]] caching is controlled by headers such as Cache-Control (max-age, private/public, no-store) and validators like ETag (a client can ask “has it changed?” and get <span class="mono">304 Not Modified</span>). A [[cdn]] caches shared responses at edges near users; the browser cache serves repeat visits for one user. Personalized or authenticated responses must be marked private or no-store.`,
          ['cdn', 'edge-cache', 'cache-hit-ratio']),
        C('latency-budget', 'Thinking in round trips',
          `Distance costs time. Light in fibre covers roughly 200 km per millisecond, so a user 6,000 km away pays about 60 ms per round trip at best — before any server work.`,
          `A cold HTTPS request costs roughly DNS (0–1 RTT to the resolver) + TCP (1 RTT) + TLS 1.3 (1 RTT) + request/response (1 RTT) + server time. Techniques that remove round trips — connection reuse, edge TLS termination, HTTP/3, DNS caching, preconnect — often beat server optimizations for user-perceived [[latency]].`,
          ['latency', 'tcp', 'tls']),
        { kind: 'anatomy', title: 'Anatomy: the path of a request', caption: 'Click any component to see what enters it, what leaves it and what goes wrong there.',
          nodes: API_ANATOMY_NODES,
          edges: [['browser', 'dns', 'lookup'], ['browser', 'edge', 'HTTPS'], ['edge', 'gw', 'forward'], ['gw', 'api', 'route'], ['api', 'db', 'query']] },
      ],
      quiz: [
        { q: 'A user in Sydney reports the <b>first</b> load of your Virginia-hosted API takes ~900 ms, but later calls take ~250 ms. Server processing is 40 ms. What explains most of the difference?',
          options: ['The database warms up its cache after the first query', 'The first call pays DNS, TCP and TLS round trips; later calls reuse the open connection', 'HTTPS encryption makes every request slow, but the browser caches the decrypted result', 'The API gateway compiles policies on the first request'],
          answer: 1, tag: 'tcp',
          why: 'With a ~200 ms RTT, DNS + TCP + TLS add several round trips only on a cold connection. Keep-alive reuse skips them, leaving roughly one RTT plus server time.',
          misconception: { 0: 'Server time is only 40 ms in both cases, so a database cache cannot account for a ~650 ms difference.', 2: 'Encryption itself is cheap; the cost is the handshake round trips, and browsers do not cache “decrypted results”.', 3: 'Gateway policy work is milliseconds; distance-driven round trips dominate here.' } },
        { q: 'What does DNS TTL control?',
          options: ['How long a TCP connection stays open', 'How long resolvers and clients may cache a name-to-address answer', 'How many hops a packet can travel', 'How long a TLS session key is valid'],
          answer: 1, tag: 'dns',
          why: 'TTL is the cache lifetime for a DNS record. It trades lookup load against how fast a change (such as failover) reaches clients.',
          misconception: { 0: 'Connection lifetime is controlled by keep-alive settings, not DNS.', 2: 'That is the IP packet TTL/hop limit — same name, different mechanism.', 3: 'TLS session lifetimes are negotiated by TLS, not by DNS records.' } },
        { q: 'Which statement about HTTPS is correct?',
          options: ['It proves the user is who they claim to be', 'It hides which IP address you are connecting to', 'It encrypts the path, query string, headers and body in transit', 'It makes it safe to put API keys in the URL'],
          answer: 2, tag: 'https',
          why: 'TLS encrypts everything inside the HTTP message in transit. It authenticates the server, not the user, and URLs still end up in logs.',
          misconception: { 0: 'Standard HTTPS authenticates the server via its certificate. User identity comes from tokens or client certificates.', 1: 'Network observers still see the destination IP (and often the hostname).', 3: 'URLs are logged by servers, proxies and browser history even though they are encrypted on the wire.' } },
        { q: 'You move a service to a new region and update DNS, but some users keep hitting the old region for an hour. Most likely cause?',
          options: ['TCP retransmissions', 'A long TTL on the DNS record, so resolvers keep the cached address', 'HTTP/2 multiplexing', 'The TLS certificate was not renewed'],
          answer: 1, tag: 'dns',
          why: 'Resolvers and clients honor the cached record until it expires. Lower the TTL well before a planned migration.',
          misconception: { 0: 'Retransmissions repair lost packets on an existing connection; they do not choose a destination.', 2: 'Multiplexing shares one connection among requests; it does not pick the region.', 3: 'An expired certificate causes connection errors, not silent routing to the old region.' } },
        { q: 'Why can HTTP/3 help mobile users on lossy networks?',
          options: ['It compresses JSON better', 'It runs over QUIC, which avoids TCP head-of-line blocking and combines transport and TLS handshakes', 'It removes the need for TLS', 'It caches responses on the phone automatically'],
          answer: 1, tag: 'http',
          why: 'QUIC streams are independent, so one lost packet does not stall all streams, and the handshake is shorter.',
          misconception: { 0: 'Compression is independent of HTTP version.', 2: 'QUIC has TLS 1.3 built in; encryption is mandatory.', 3: 'Caching is controlled by headers, not by the HTTP version.' } },
      ],
      teachback: { prompt: 'Explain to a new teammate what happens, step by step, between typing an HTTPS URL and receiving JSON — and where the time goes on a cold request.',
        rubric: 'URL parsing and browser cache; DNS resolution via resolvers with TTL; TCP handshake 1 RTT; TLS handshake (1 RTT in 1.3) with certificate validation; HTTP request with method/headers/body; edge/CDN/gateway; server work; response with status/headers; keep-alive reuse removes handshakes; distance/RTT dominates cold latency.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-netflix-open-connect', 'case-incident-meta-2021'], patternRefs: ['p-cdn-edge', 'p-connection-pooling'],
    },

    {
      id: 'l0-apis', level: 0, minutes: 25,
      title: 'APIs, REST and the frontend/backend split',
      summary: 'What an API actually is, how REST uses HTTP methods, status codes, headers, query parameters and JSON, and why the backend never trusts the client.',
      prereqs: ['l0-url-journey'],
      outcomes: [
        'You can define an API as a contract and explain why contracts matter more than code.',
        'You can choose the right HTTP method and status code for an operation.',
        'You can explain which HTTP methods are safe and which are idempotent.',
        'You can explain why validation and authorization live on the backend.',
      ],
      sections: [
        C('what-api', 'An API is a contract',
          `An [[api|API]] (Application Programming Interface) is a promise: “send me a request shaped like this, and I will answer with data shaped like that.” The caller does not need to know how the work is done.`,
          `A web API exposes operations over HTTP. Its contract covers endpoints, methods, request and response schemas, error formats, authentication, rate limits and versioning. Because many clients depend on it, the contract changes more slowly than the code behind it — breaking it breaks other people’s software.`,
          ['api', 'api-contract']),
        C('frontend-backend', 'Frontend versus backend',
          `The [[frontend]] is what runs on the user’s device: screens, buttons, the chat window. The [[backend]] runs on servers you control: it holds the data, applies business rules and talks to databases and models.`,
          `Anything in the frontend can be read and modified by the user, so it can never be trusted with secrets, authorization decisions or final validation. The frontend may validate for convenience (fast feedback); the backend must validate for correctness and security.`,
          ['frontend', 'backend'],
          `“The UI hides the button” is not access control. Users can call the API directly.`),
        C('rest', 'REST: resources and verbs',
          `[[rest|REST]] organizes an API around <b>things</b> (resources) rather than actions. Property A is <span class="mono">/properties/A</span>; its lease is <span class="mono">/properties/A/lease</span>. HTTP methods say what to do to the thing.`,
          `Resources are nouns with stable URLs; representations are usually JSON. Interactions are stateless: each request carries everything needed to process it (including the auth token), which lets any replica handle any request. REST is a style, not a standard; many “REST” APIs are pragmatic HTTP+JSON APIs, which is fine if consistent.`,
          ['rest', 'stateless']),
        {
          kind: 'table', title: 'HTTP methods and their guarantees',
          head: ['Method', 'Typical use', 'Safe (no side effects)?', 'Idempotent (repeat = same effect)?'],
          rows: [
            ['GET', 'Read a resource or list', 'Yes', 'Yes'],
            ['POST', 'Create, or trigger an action', 'No', 'No — unless you add an idempotency key'],
            ['PUT', 'Replace a resource at a known URL', 'No', 'Yes'],
            ['PATCH', 'Partially update a resource', 'No', 'Not guaranteed — depends on the patch'],
            ['DELETE', 'Remove a resource', 'No', 'Yes (second delete finds nothing to remove)'],
          ],
        },
        C('methods', 'Why idempotency of methods matters',
          `Networks fail mid-request. If a client does not know whether a request succeeded, it wants to retry. That is only safe if repeating the request cannot cause a second effect.`,
          `GET, PUT and DELETE are defined as [[idempotency|idempotent]] in HTTP semantics, so clients and proxies may retry them. POST is not: retrying “create booking” can create two bookings. The standard fix is an [[idempotency-key]] header: the server stores the key with the first result and returns the stored result for repeats.`,
          ['idempotency', 'http-methods', 'idempotency-key']),
        C('status', 'Status codes tell the client what to do next',
          `The status code is a one-number summary: 2xx “it worked”, 4xx “you sent something wrong”, 5xx “we failed”.`,
          `Key codes: 200 OK, 201 Created, 202 Accepted (async work started), 204 No Content, 304 Not Modified, 400 Bad Request (malformed/invalid), 401 Unauthorized (not authenticated), 403 Forbidden (authenticated but not allowed), 404 Not Found, 409 Conflict (e.g. seat already taken), 422 Unprocessable Content (well-formed but semantically invalid), 429 Too Many Requests (rate limited — honor Retry-After), 500 Internal Server Error, 502/504 gateway errors, 503 Service Unavailable (overloaded or down). Clients should retry some 5xx and 429 with backoff, and never blindly retry 4xx.`,
          ['status-codes', 'http-429']),
        C('headers-query', 'Headers, query parameters and bodies',
          `Headers carry metadata (who you are, what format you send and want). Query parameters refine a read (<span class="mono">?status=active&page=2</span>). The body carries the data you send.`,
          `Common headers: Authorization (bearer token), Content-Type and Accept (media types), Idempotency-Key, Cache-Control, ETag/If-None-Match, traceparent (distributed tracing). Query parameters are for filtering, sorting and pagination of GET requests. Bodies — typically [[json]] — carry create/update payloads. Keep sensitive data out of URLs (they are logged).`,
          ['headers', 'json']),
        C('json', 'JSON payloads and types',
          `[[json|JSON]] is a text format for structured data: objects with named fields, lists, strings, numbers, true/false and null.`,
          `JSON has no native date, decimal or integer-size types, so contracts must specify formats (ISO-8601 timestamps, currency as string or integer minor units, IDs as strings to avoid precision loss in JavaScript numbers above 2<sup>53</sup>). Use a schema ([[json-schema]]) to declare required fields, types, ranges and whether extra fields are allowed.`,
          ['json', 'json-schema']),
        W('url-journey', 'Experiment: the request/response round trip',
          'Step through the journey again and focus on the HTTP request and response stages: what the client sends (method, headers, body) and what comes back (status, headers, JSON).'),
        { kind: 'anatomy', title: 'Anatomy: frontend, API, data', caption: 'The backend is the trust boundary. Click each part.',
          nodes: API_ANATOMY_NODES.filter((n) => n.id !== 'dns'),
          edges: [['browser', 'edge', 'HTTPS + token'], ['edge', 'gw'], ['gw', 'api', 'validated'], ['api', 'db', 'SQL']] },
        NOTE('tip', 'Design the error format once: a machine-readable code, a human message, the field that failed, and a correlation ID that matches your logs. RFC 9457 “Problem Details for HTTP APIs” is a widely used standard shape.'),
      ],
      quiz: [
        { q: 'A mobile client times out on <span class="mono">POST /bookings</span> and retries. The customer is charged twice. What is the root design flaw?',
          options: ['The API used JSON instead of a binary format', 'POST is not idempotent and the API accepted no idempotency key to deduplicate retries', 'The client should have used GET', 'The server returned 500 instead of 503'],
          answer: 1, tag: 'idempotency-key',
          why: 'Retries are unavoidable; the server must recognize a repeated attempt (idempotency key stored with the first result) and return the original outcome.',
          misconception: { 0: 'Encoding has nothing to do with duplicate side effects.', 2: 'GET must not have side effects; using it for creation breaks HTTP semantics and caching.', 3: 'Status codes guide retries, but the duplicate occurred because the server could not detect a repeat.' } },
        { q: 'A logged-in user requests another tenant’s invoice. Which status code is most appropriate?',
          options: ['401 Unauthorized', '403 Forbidden (or 404 to avoid revealing existence)', '400 Bad Request', '500 Internal Server Error'],
          answer: 1, tag: 'authorization',
          why: 'The user is authenticated but not authorized. Many APIs return 404 for other tenants’ resources so attackers cannot probe which IDs exist.',
          misconception: { 0: '401 means “not authenticated”; this user is authenticated.', 2: 'The request is well-formed; the problem is permission.', 3: 'Nothing failed on the server; it correctly refused.' } },
        { q: 'Which method should replace the entire lease document at <span class="mono">/properties/A/lease</span> and be safely retryable?',
          options: ['POST', 'PUT', 'GET', 'PATCH with an increment operation'],
          answer: 1, tag: 'http-methods',
          why: 'PUT replaces the resource at a known URL; sending the same body twice yields the same state.',
          misconception: { 0: 'POST is for creating or triggering actions and is not idempotent.', 2: 'GET must not modify state.', 3: 'An increment patch applied twice increments twice — not idempotent.' } },
        { q: 'Why must the backend validate input even if the frontend already does?',
          options: ['Frontend validation is slower', 'Anyone can call the API directly or modify the frontend, so client checks are only a convenience', 'Browsers strip validation attributes', 'JSON cannot carry validation rules'],
          answer: 1, tag: 'backend',
          why: 'The backend is the trust boundary. Client-side checks improve UX but provide no security.',
          misconception: { 0: 'Speed is not the reason; client validation is often faster.', 2: 'Browsers do not strip anything; the issue is that the client is under the user’s control.', 3: 'Validation rules live in schemas and code, not in JSON payloads.' } },
        { q: 'Your API returns 429 with a Retry-After header. What should a well-behaved client do?',
          options: ['Retry immediately in a tight loop', 'Wait at least the Retry-After time, then retry with backoff and jitter', 'Treat it as permanent failure and never retry', 'Switch to POST'],
          answer: 1, tag: 'http-429',
          why: '429 means “slow down”. Honoring Retry-After plus jittered backoff prevents synchronized retry waves.',
          misconception: { 0: 'Immediate retries amplify the overload that caused the 429.', 2: '429 is temporary by definition.', 3: 'The method does not change rate-limit policy.' } },
      ],
      teachback: { prompt: 'Explain to a junior developer what makes a good REST API contract for “get Property A’s lease” and “create a booking”.',
        rubric: 'Resource-oriented URLs; correct methods (GET read, POST create); safe/idempotent semantics; idempotency key for POST; status codes 200/201/400/401/403/404/409/429; headers (Authorization, Content-Type); JSON schema with types and formats; backend validation and authorization; consistent error format with correlation ID.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-payments-idempotency'], patternRefs: ['p-idempotency'],
    },

    {
      id: 'l0-execution', level: 0, minutes: 30,
      title: 'Processes, threads, event loops and async I/O',
      summary: 'How a server actually runs many requests at once: concurrency versus parallelism, blocking versus non-blocking I/O, CPU-bound versus I/O-bound work.',
      prereqs: ['l0-apis'],
      outcomes: [
        'You can explain concurrency versus parallelism with a concrete example.',
        'You can say whether a workload is CPU-bound or I/O-bound and what that implies.',
        'You can explain how one blocking call can freeze an async server.',
        'You can explain why thread pools run out while CPU stays low.',
      ],
      sections: [
        C('sync-async', 'Synchronous versus asynchronous execution',
          `Synchronous: do one step, wait for it to finish, then do the next. Asynchronous: start a step, and while it is in progress go do something else; come back when it is done.`,
          `In synchronous code the caller is suspended until a call returns. In asynchronous code an operation returns a handle (a future/promise/awaitable) immediately; the runtime resumes the caller when the result is ready. Async matters when steps involve <b>waiting</b> (network, disk) — it lets the waiting time be used for other work.`,
          ['async-io', 'blocking-io']),
        C('process-thread', 'Processes and threads',
          `A [[process]] is a running program with its own memory. A [[thread]] is a line of execution inside a process; threads in one process share memory.`,
          `The OS schedules threads onto CPU cores. Processes are isolated (a crash in one does not corrupt another) but cost more memory and need explicit communication. Threads are cheaper and share data but need synchronization (locks) to avoid races. Each thread reserves a stack (often hundreds of KB to MB), so tens of thousands of threads are expensive. In standard CPython, the global interpreter lock allows only one thread to execute Python bytecode at a time, so CPU-bound Python uses multiple processes for parallelism.`,
          ['process', 'thread']),
        C('event-loop', 'The event loop',
          `An [[event-loop]] is a single worker that juggles many tasks. It runs a task until that task has to wait, parks it, and immediately picks up another task that is ready.`,
          `The loop uses OS readiness notifications (epoll, kqueue, IOCP) to learn when sockets have data. Handlers must cooperate: they <b>yield</b> at every await. Node.js, Python asyncio, and many modern servers use this model. A single loop can hold thousands of in-flight network calls because a waiting request costs only a small object, not a thread.`,
          ['event-loop', 'non-blocking-io'],
          `The event loop is not magic: CPU work inside a handler (parsing a 20 MB PDF, a tight loop, a synchronous HTTP client) runs without yielding and stops <b>every</b> other request on that loop.`),
        C('blocking', 'Blocking versus non-blocking I/O',
          `Blocking I/O: the thread stops and sleeps until the data arrives. Non-blocking I/O: the thread asks for data, gets told “not ready yet”, and keeps working on other things.`,
          `[[blocking-io|Blocking]] calls are fine in a thread-per-request server as long as there are enough threads. In an async server, a blocking call (a synchronous database driver, <span class="mono">sleep</span>, a sync SDK) stalls the loop. Common fixes: use async drivers, or offload the blocking call to a bounded thread pool so the loop stays free.`,
          ['blocking-io', 'non-blocking-io']),
        C('cpu-io', 'CPU-bound versus I/O-bound',
          `[[cpu-bound|CPU-bound]] work is limited by how fast the processor computes (resizing images, tokenizing a large document, running a model locally). [[io-bound|I/O-bound]] work is limited by waiting on something else (database, network, an LLM API).`,
          `An LLM chatbot API is overwhelmingly I/O-bound: a request might use 10–20 ms of CPU and spend 2–10 s waiting on retrieval and model generation. Scaling advice differs completely: CPU-bound work needs more cores or processes; I/O-bound work needs more concurrency (async, larger pools) — and a downstream that can handle it.`,
          ['cpu-bound', 'io-bound']),
        C('conc-par', 'Concurrency is not parallelism',
          `[[concurrency|Concurrency]] is <b>dealing with</b> many things at once — like one chef juggling five dishes, switching while each simmers. [[parallelism|Parallelism]] is <b>doing</b> many things at the same instant — five chefs each cooking one dish.`,
          `A single-core event loop can be highly concurrent (thousands of requests in progress) with zero parallelism. Parallelism needs multiple cores, processes or machines. I/O-bound servers mostly need concurrency; CPU-bound pipelines need parallelism. Many systems need both: multiple processes (parallelism across cores), each running an event loop (concurrency within a core).`,
          ['concurrency', 'parallelism']),
        W('concurrency-parallelism', 'Animation: one juggler versus many workers',
          'Compare one core switching between tasks with four cores running tasks simultaneously. Make the tasks I/O-heavy, then CPU-heavy, and watch which approach wins in each case.'),
        CMP('cmp-async-sync'),
        C('threadpool', 'Thread pools and why they run out',
          `Most thread-per-request servers keep a fixed pool of worker threads. When every thread is busy waiting on a slow database or LLM, new requests stand in line — even though the CPU has nothing to do.`,
          `Pool size caps concurrency per replica. If each request waits 4 s on the LLM and a replica has 50 threads, the replica can complete at most 50 / 4 = 12.5 requests per second, regardless of CPU. Extra arrivals queue in the server’s accept queue, latency climbs, and eventually clients time out. This is the most common reason for “CPU 20%, latency rising”.`,
          ['thread', 'little-law', 'concurrency']),
        W('threadpool-blocking', 'Experiment: CPU is idle but requests are waiting',
          'Increase the downstream wait and watch the pool fill. CPU utilization stays low while the queue and latency grow. Then switch to non-blocking I/O and compare.'),
        C('context-switch', 'The cost of switching',
          `Switching between threads is not free: the OS saves and restores state and caches go cold.`,
          `Thousands of OS threads mean frequent context switches and memory overhead. Async tasks switch in user space at well-defined await points, which is much cheaper. That is why async servers handle very high connection counts — but also why they depend on every task yielding promptly.`,
          ['thread', 'event-loop']),
      ],
      quiz: [
        { q: 'An async Python API handles 2,000 concurrent chats fine. After a change, latency for <b>all</b> users spikes whenever one user uploads a large PDF, yet average CPU is only 30%. Most likely cause?',
          options: ['The database ran out of disk space', 'PDF parsing runs synchronously inside the event loop, blocking every other request on it', 'TLS handshakes got slower', 'The LLM provider throttled the account'],
          answer: 1, tag: 'event-loop',
          why: 'CPU-heavy work inside an async handler does not yield. One core is pegged (average CPU looks modest across cores) and every request on that loop waits. Offload parsing to a worker pool or a separate service.',
          misconception: { 0: 'Disk exhaustion causes write failures, not latency spikes correlated with uploads.', 2: 'Handshakes do not depend on another user’s upload.', 3: 'Throttling would show 429s and affect LLM calls, not correlate with PDF uploads.' } },
        { q: 'Which statement is true?',
          options: ['Concurrency requires multiple CPU cores', 'A single-threaded event loop can be highly concurrent without any parallelism', 'Parallelism and concurrency are two names for the same thing', 'Async I/O makes each individual database query faster'],
          answer: 1, tag: 'concurrency',
          why: 'Concurrency is about overlapping the progress of tasks; parallelism is simultaneous execution. One core can interleave thousands of waiting tasks.',
          misconception: { 0: 'Concurrency only needs task switching; one core suffices.', 2: 'They are distinct: you can have either without the other.', 3: 'Async does not speed up the query; it lets other work proceed while waiting.' } },
        { q: 'A service resizes images (CPU-heavy). Moving it from a sync framework to async I/O will most likely…',
          options: ['Greatly increase throughput', 'Barely change throughput, because the bottleneck is CPU, not waiting', 'Reduce memory to zero', 'Make it I/O-bound'],
          answer: 1, tag: 'cpu-bound',
          why: 'Async helps when time is spent waiting. CPU-bound work needs more cores, processes, or a better algorithm.',
          misconception: { 0: 'There is little waiting to overlap; the CPU is the constraint.', 2: 'Memory use is unrelated to the I/O model in this way.', 3: 'The workload’s nature does not change with the framework.' } },
        { q: 'Each replica has 40 worker threads. Every request waits ~2 s on the LLM. Roughly what is the maximum throughput per replica?',
          options: ['~2 requests/s', '~20 requests/s', '~80 requests/s', 'Unlimited, because CPU is low'],
          answer: 1, tag: 'little-law',
          why: 'Throughput ≤ concurrency / time per request = 40 / 2 s = 20 req/s. This is Little’s Law rearranged.',
          misconception: { 0: 'That would be 4 threads, not 40.', 2: 'That assumes 0.5 s per request.', 3: 'Threads, not CPU, cap a blocking server here.' } },
        { q: 'Why do async servers usually need far less memory per in-flight request than thread-per-request servers?',
          options: ['They compress requests', 'A waiting async task is a small heap object, while each thread reserves its own stack', 'They do not use the heap', 'They store requests on disk'],
          answer: 1, tag: 'async-io',
          why: 'Thread stacks are reserved per thread; async tasks keep only the state needed to resume.',
          misconception: { 0: 'Compression is unrelated.', 2: 'Async tasks live on the heap.', 3: 'In-flight request state is in memory in both models.' } },
      ],
      teachback: { prompt: 'Explain why an LLM-backed API can have low CPU usage but high latency, using the words thread, event loop, blocking and I/O-bound.',
        rubric: 'Requests are I/O-bound (waiting on retrieval/LLM); in thread-per-request servers each wait pins a thread; pool exhaustion queues requests while CPU idles; async/event loop holds many waits cheaply; but blocking or CPU-heavy work in the loop stalls everyone; fix with async drivers, offloading, bounded pools; concurrency vs parallelism distinction.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-llm-inference'], patternRefs: ['p-async-parallel', 'p-connection-pooling'],
    },

    {
      id: 'l0-resources', level: 0, minutes: 30,
      title: 'Latency, throughput, concurrency and capacity',
      summary: 'The vocabulary of performance: resources and contention, percentiles, Little’s Law, and why latency explodes as utilization approaches 100%.',
      prereqs: ['l0-execution'],
      outcomes: [
        'You can define latency, throughput, concurrency and capacity precisely.',
        'You can use Little’s Law to estimate how many requests are in flight.',
        'You can explain why p99 matters more than the average.',
        'You can explain why a system with 20% CPU can still be overloaded.',
      ],
      sections: [
        C('resources', 'The resources every request consumes',
          `Every request borrows things: a bit of CPU time, some memory, network bandwidth, disk reads, a database connection, a slot in a thread pool, part of an LLM quota. Whatever runs out first limits the whole system.`,
          `Resources include hardware (CPU, memory, disk I/O, network I/O) and <b>logical</b> resources (worker threads, connection pools, file descriptors, locks, rate-limit quotas such as [[tpm|tokens per minute]]). Monitoring often shows only the hardware ones, which is why logical bottlenecks hide.`,
          ['capacity']),
        C('contention', 'Resource contention',
          `Contention is many requests wanting the same limited thing at the same time — like ten people waiting for one printer.`,
          `Contention appears as waiting: queueing for a connection from the [[connection-pool]], waiting on a database row [[lock]], waiting for a GC pause, or waiting for a rate-limit token. Waiting consumes wall-clock time but no CPU, so CPU graphs look healthy while latency degrades.`,
          ['connection-pool', 'lock']),
        C('latency', 'Latency',
          `[[latency|Latency]] is how long one request takes from the user’s point of view.`,
          `End-to-end latency = network time + queueing time + service time across every hop. For streaming LLM responses, separate [[ttft|time to first token]] (perceived responsiveness) from total generation time. Always report latency as a distribution — [[p99|p50, p95, p99]] — not a single average.`,
          ['latency', 'ttft', 'p99']),
        C('percentiles', 'Percentiles and tail latency',
          `p50 is the typical request. p99 means 99% of requests were faster than this — the slowest 1% are worse. If a page makes 20 backend calls, the slow tail hits most users.`,
          `Averages hide the tail: 98 requests at 100 ms and 2 at 10 s average 296 ms, which describes nobody. Tail latency grows with fan-out: if a request calls 20 services each with a 1% chance of being slow, about 1 − 0.99<sup>20</sup> ≈ 18% of requests see at least one slow call.`,
          ['p99']),
        C('throughput', 'Throughput and capacity',
          `[[throughput|Throughput]] is how many requests finish per second. [[capacity|Capacity]] is the maximum throughput you can sustain while still meeting your latency goal.`,
          `Throughput rises with load until a resource saturates; beyond that, extra load only adds queueing (latency) and errors. Capacity is defined against an objective (“p95 under 3 s”), not at the point of collapse.`,
          ['throughput', 'capacity', 'slo']),
        C('littles-law', 'Little’s Law',
          `If 100 requests arrive per second and each takes 2 seconds, then on average about 200 requests are inside the system at any moment. That simple multiplication is [[little-law|Little’s Law]].`,
          `<b>L = λ × W</b>: average number in the system (L) equals arrival rate (λ) times average time in the system (W). It holds for any stable system regardless of distribution. Uses: size pools (need ~λ × W concurrent slots), sanity-check metrics, and see that if W rises (slow LLM), L rises too — exhausting threads, connections and memory.`,
          ['little-law', 'concurrency']),
        W('littles-law', 'Calculator: concurrency you need',
          'Set arrivals per second and time per request. See how many in-flight slots you need, then compare with the pool sizes you actually have.'),
        C('utilization', 'Why latency explodes near 100% utilization',
          `A cashier who is busy 50% of the time rarely makes you wait. One who is busy 95% of the time almost always has a line — and it grows fast.`,
          `In simple queueing models, waiting time scales roughly with ρ / (1 − ρ), where ρ is utilization of the bottleneck resource. At ρ = 0.5 the factor is 1; at 0.9 it is 9; at 0.99 it is 99. Plan to run bottleneck resources well below saturation and remember that utilization of the <b>bottleneck</b> — maybe a pool or a quota — matters, not CPU.`,
          ['latency', 'capacity'],
          `“We’re only at 20% CPU so we have 5× headroom” is wrong whenever the bottleneck is not CPU.`),
        C('low-cpu', 'CPU 20%, memory 50%, p99 climbing',
          `This classic symptom means requests are <b>waiting</b>, not computing. Something other than CPU is full.`,
          `Usual suspects: worker/thread pool exhausted by slow downstream calls; database [[connection-pool]] exhausted; lock contention; event loop blocked by a synchronous call; LLM rate limit ([[http-429|429s]]) with retries; queue backlog; garbage-collection pauses; network latency to a dependency. Diagnose by checking in-flight requests, pool wait times, dependency latency and error codes — not by adding CPU.`,
          ['blocking-io', 'connection-pool', 'http-429', 'backpressure']),
        W('chatbot-load', 'Simulator: load an AI chatbot backend',
          'Raise traffic until latency climbs. Watch which resource saturates first — it is rarely CPU. Then try fewer replicas, a smaller database pool, or a slower LLM.'),
        C('io-types', 'Memory, network I/O and disk I/O',
          `Memory holds in-flight state; network I/O moves bytes between machines; disk I/O reads and writes storage.`,
          `Memory pressure shows as GC pauses or OOM kills — common when large prompts, retrieved chunks or buffered responses are held per request (memory ≈ in-flight requests × bytes per request, so it rises with latency via Little’s Law). Network I/O limits include bandwidth, connection counts and per-hop latency. Disk I/O limits (IOPS, throughput) mostly bite databases and logging.`,
          ['latency']),
      ],
      quiz: [
        { q: 'Your API has CPU at 20%, memory at 50%, and p99 latency doubling every 10 minutes during a traffic increase. What should you inspect first?',
          options: ['Upgrade to larger VMs with more CPU', 'In-flight requests, pool wait times (threads, DB connections), dependency latency and 429/timeout counts', 'Disk space on the API servers', 'The TLS cipher configuration'],
          answer: 1, tag: 'connection-pool',
          why: 'Low CPU plus rising latency means requests are waiting on something. Saturation of a logical resource or a slow dependency is the likely cause.',
          misconception: { 0: 'More CPU does nothing when CPU is not the bottleneck.', 2: 'Disk space would cause errors, not gradual latency growth correlated with traffic.', 3: 'Cipher choice affects handshake cost, which is CPU work — and CPU is low.' } },
        { q: 'A service receives 300 req/s and each request spends 4 s in the system. How many requests are in flight on average?',
          options: ['75', '304', '1,200', 'Cannot be determined'],
          answer: 2, tag: 'little-law',
          why: 'Little’s Law: L = λ × W = 300 × 4 = 1,200.',
          misconception: { 0: 'That divides instead of multiplies.', 1: 'Adding the numbers has no meaning here.', 3: 'Little’s Law needs only average arrival rate and average time in system.' } },
        { q: 'Average latency is 300 ms but users complain about slowness. Why might both be true?',
          options: ['Users are wrong', 'The average hides a long tail: p99 could be several seconds', 'Average latency is always higher than p99', 'Latency does not affect users'],
          answer: 1, tag: 'p99',
          why: 'Tail latency, especially with fan-out, determines the experience of many users. Track p95/p99.',
          misconception: { 0: 'Complaints often come from the tail that averages hide.', 2: 'p99 is usually much higher than the average.', 3: 'Latency is the core user-visible performance metric.' } },
        { q: 'The bottleneck resource is at 90% utilization. Roughly how does queueing delay compare with running it at 50%?',
          options: ['About the same', 'Roughly 1.8× more', 'Roughly 9× more', 'Lower, because the system is warmed up'],
          answer: 2, tag: 'capacity',
          why: 'With the ρ/(1−ρ) approximation: 0.9/0.1 = 9 versus 0.5/0.5 = 1. Delay grows nonlinearly near saturation.',
          misconception: { 0: 'Queueing is highly nonlinear in utilization.', 1: 'That treats delay as proportional to utilization; it is not.', 3: 'Warm-up effects do not offset queueing.' } },
        { q: 'Why does memory usage often rise when a downstream LLM gets slower, even though traffic is unchanged?',
          options: ['The LLM sends larger responses', 'More requests are in flight at once (L = λ × W), each holding its prompt and context in memory', 'Garbage collection is disabled under load', 'Memory leaks only appear during slowness'],
          answer: 1, tag: 'little-law',
          why: 'Higher W at the same λ means more concurrent requests, each holding state.',
          misconception: { 0: 'Response size does not have to change for memory to grow.', 2: 'GC is not disabled; it may struggle more with more live objects.', 3: 'This is expected growth, not necessarily a leak.' } },
      ],
      teachback: { prompt: 'Explain to a product manager why “CPU is only 20%” does not mean the chatbot backend has 5× headroom.',
        rubric: 'Requests are I/O-bound and wait; logical resources (threads, DB/HTTP connection pools, LLM TPM/RPM quotas, locks) saturate first; Little’s Law links latency to in-flight count; queueing delay grows nonlinearly near saturation of the bottleneck; percentiles show the impact; capacity defined against latency objective.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-llm-inference'], patternRefs: ['p-connection-pooling', 'p-backpressure-shedding', 'p-observability-slo'],
    },

    {
      id: 'l0-scaling', level: 0, minutes: 30,
      title: 'Scaling, state, services and containers',
      summary: 'Horizontal versus vertical scaling, stateless versus stateful services, monolith versus microservices, containers and orchestration — and how to reason before picking cloud services.',
      prereqs: ['l0-resources'],
      outcomes: [
        'You can explain why stateless services scale horizontally and stateful ones resist it.',
        'You can argue for or against microservices with concrete trade-offs.',
        'You can explain what a container image is and what an orchestrator does.',
        'You can reason from requirements to architecture before naming any cloud product.',
      ],
      sections: [
        C('vertical', 'Vertical scaling',
          `[[vertical-scaling|Vertical scaling]] means making one machine bigger: more CPU, more memory.`,
          `It requires no code change and suits components that are hard to distribute, such as a primary relational database. Limits: a ceiling at the largest instance, cost that grows faster than capacity at the top end, a single failure domain, and often a restart to resize.`,
          ['vertical-scaling']),
        C('horizontal', 'Horizontal scaling',
          `[[horizontal-scaling|Horizontal scaling]] means running more copies ([[replica|replicas]]) of a service and spreading requests across them.`,
          `It needs a [[load-balancer]] and services that do not keep important data in local memory. It raises the ceiling and adds redundancy. It does not help if the bottleneck is a shared dependency: ten replicas sharing one database with 100 connections still have 100 connections.`,
          ['horizontal-scaling', 'replica', 'load-balancer'],
          `Adding replicas can make things worse: each replica opens its own DB connection pool, so 20 replicas × 20 connections = 400 connections against a database that allows 300.`),
        CMP('cmp-horizontal-vertical'),
        C('stateless', 'Stateless versus stateful',
          `A [[stateless]] service forgets everything between requests; any copy can answer any request. A [[stateful]] service remembers something locally (a session, a cache, a file), so requests must find the right copy.`,
          `Make the request path stateless by moving state into shared stores: sessions in [[redis|Redis]] or signed tokens, files in object storage, conversation history in a database. Stateful systems (databases, brokers, caches) scale through [[replication]] and [[partitioning]], which is harder and covered in Level 3–4.`,
          ['stateless', 'stateful']),
        C('monolith', 'Monolith versus microservices',
          `A [[monolith]] is one deployable application. [[microservices|Microservices]] split the system into many small services that talk over the network.`,
          `The real trade-off is organizational and operational: independent deploys and scaling versus network calls, partial failures, distributed data, and a heavier platform. A modular monolith — clean internal boundaries, one deployment — is a strong default.`,
          ['monolith', 'microservices']),
        CMP('cmp-monolith-microservices'),
        C('containers', 'Containers and images',
          `A [[container]] packages your app with everything it needs to run — runtime, libraries, config defaults — so it runs the same on a laptop and in production.`,
          `A container image ([[docker|Docker]]/OCI format) is an immutable, layered filesystem plus metadata (entry command, exposed ports). Containers share the host kernel and are isolated with namespaces and cgroups, so they start faster and are lighter than virtual machines. Images are versioned and stored in a registry; deployments reference an exact image digest for reproducibility.`,
          ['container', 'docker']),
        C('orchestration', 'Orchestration',
          `Running one container is easy. Running hundreds — restarting crashed ones, spreading them across machines, rolling out new versions — needs an [[orchestration|orchestrator]].`,
          `Orchestrators (Kubernetes, and managed platforms built on it such as Azure Container Apps and AKS) schedule containers onto nodes, restart failed ones, run health probes, perform rolling updates, provide service discovery and scale replicas on metrics. They make horizontal scaling routine but add their own configuration surface.`,
          ['orchestration', 'autoscaling']),
        W('chatbot-load', 'Simulator: when do more replicas stop helping?',
          'Add replicas while traffic is high. Throughput improves until a shared resource (database connections or the LLM quota) saturates — after that, more replicas add cost, not capacity.'),
        {
          kind: 'steps', title: 'Reason about the system before choosing any cloud service',
          steps: [
            { title: 'What must it do?', text: 'Functional requirements: the operations and the data.' },
            { title: 'How well?', text: 'Latency targets (p95/p99), availability, consistency, data retention, security and tenant isolation.' },
            { title: 'How much?', text: 'Requests per second at peak, concurrency (Little’s Law), data volume and growth, read/write ratio.' },
            { title: 'Where does time go?', text: 'Trace one request: which steps are CPU-bound, which are waits on dependencies.' },
            { title: 'What saturates first?', text: 'Name the bottleneck resource at peak — pool, quota, lock, CPU, bandwidth.' },
            { title: 'Simplest design that works', text: 'Draw it. Add queues, caches, replicas or partitions only where a number justifies them.' },
            { title: 'Only now pick services', text: 'Map each component to a product (Container Apps, Azure SQL, Service Bus…) by fit, limits and operational cost.' },
          ],
        },
        NOTE('warn', 'Autoscaling reacts after load arrives. New replicas take time to start (image pull, warm-up), and they do not help if the bottleneck is downstream. For predictable peaks such as a live match, pre-scale.'),
      ],
      quiz: [
        { q: 'You scale an API from 5 to 20 replicas during a spike. Latency gets <b>worse</b> and the database reports “too many connections”. Why?',
          options: ['The load balancer is misconfigured', 'Each replica opens its own connection pool, so total connections exceed the database limit', 'Replicas share CPU and slow each other down', 'Horizontal scaling never works for APIs'],
          answer: 1, tag: 'connection-pool',
          why: 'Connection count scales with replicas × pool size. The shared database became the bottleneck. Cap pools, use a connection proxy/pooler, or reduce per-request DB work.',
          misconception: { 0: 'The LB distributes traffic fine; the error comes from the database.', 2: 'Replicas generally run on separate resources.', 3: 'It works when the service is the bottleneck, which it no longer is here.' } },
        { q: 'Which change makes a chat API safe to scale horizontally?',
          options: ['Store each user’s conversation history in the replica’s memory', 'Store conversation history in a shared database or cache and keep replicas stateless', 'Use sticky sessions forever', 'Run one very large replica'],
          answer: 1, tag: 'stateless',
          why: 'Externalized state lets any replica serve any request, survive replica loss, and scale freely.',
          misconception: { 0: 'In-memory state is lost on restart and pins users to replicas.', 2: 'Sticky sessions are a workaround that breaks on failures and scale-in.', 3: 'That is vertical scaling and a single point of failure.' } },
        { q: 'A 6-person startup is building its first product. Which architecture is the stronger default?',
          options: ['Twenty microservices from day one', 'A modular monolith with clear internal boundaries', 'One serverless function per database table', 'A service mesh with multi-region active-active'],
          answer: 1, tag: 'monolith',
          why: 'Microservices solve organizational scaling problems the team does not have yet; the overhead would slow them down.',
          misconception: { 0: 'The operational cost dwarfs the benefit at this size.', 2: 'This fragments logic and multiplies cold starts and deployment units.', 3: 'Massive complexity with no requirement justifying it.' } },
        { q: 'What does a container image guarantee?',
          options: ['That the app will never crash', 'The same filesystem, dependencies and start command wherever it runs', 'Automatic horizontal scaling', 'Isolation equivalent to a separate physical server'],
          answer: 1, tag: 'container',
          why: 'Images are immutable and reproducible. Scaling and isolation come from the platform; containers share the host kernel.',
          misconception: { 0: 'Bugs ship inside images too.', 2: 'Scaling is the orchestrator’s job.', 3: 'Containers share a kernel; isolation is weaker than separate hardware or VMs.' } },
        { q: 'Traffic for a live cricket final will jump 20× at a known time. Best approach?',
          options: ['Rely entirely on reactive CPU autoscaling', 'Pre-scale ahead of the event and keep autoscaling as a safety net', 'Scale vertically during the match', 'Turn off autoscaling'],
          answer: 1, tag: 'autoscaling',
          why: 'Reactive autoscaling lags behind a step change; replicas take time to start. Known peaks should be provisioned in advance.',
          misconception: { 0: 'Autoscaling reacts after the spike hits and may not catch up in time.', 2: 'Resizing usually restarts instances — mid-event.', 3: 'You still want automatic response to unexpected load.' } },
      ],
      teachback: { prompt: 'Explain to an engineering manager when you would scale horizontally, when vertically, and why adding replicas does not always add throughput.',
        rubric: 'Horizontal needs stateless services and a load balancer, adds redundancy; vertical suits stateful cores, has a ceiling; shared bottleneck (DB connections, LLM quota) caps throughput; replicas × pool size can exceed DB limits; autoscaling lag and pre-scaling; reason from requirements and bottleneck before products.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-hotstar'], patternRefs: ['p-horizontal-stateless', 'p-load-balancing', 'p-capacity-prescaling'],
    },

    /* ---------------------------------------------------------------- L1 */
    {
      id: 'l1-contracts', level: 1, minutes: 25,
      title: 'API contracts and strict validation',
      summary: 'Design request and response contracts that reject bad input early: JSON Schema, required and allowed fields, pagination, filtering, sorting and versioning.',
      prereqs: ['l0-apis'],
      outcomes: [
        'You can write the rules (not the code) for a strict request schema.',
        'You can explain why rejecting unexpected properties improves safety.',
        'You can choose cursor versus offset pagination with reasons.',
        'You can evolve an API without breaking existing clients.',
      ],
      sections: [
        C('contract-first', 'Contract first',
          `Before writing any handler, write down exactly what a valid request and response look like. That written agreement is the [[api-contract|API contract]].`,
          `Contracts are typically expressed in OpenAPI (for endpoints) using [[json-schema|JSON Schema]] (for payloads). The contract drives validation, documentation, client generation and contract tests. For AI systems, the same idea applies to tool schemas and structured LLM outputs: a model’s output is just another untrusted input that must match a schema.`,
          ['api-contract', 'json-schema']),
        C('schema-rules', 'What a strict schema specifies',
          `A good schema says which fields must be present, what type each one is, what values are allowed, and that nothing else is accepted.`,
          `<ul><li><b>required</b>: fields that must exist (e.g. <span class="mono">propertyId</span>, <span class="mono">question</span>).</li><li><b>types and formats</b>: string, integer, ISO-8601 date-time, UUID.</li><li><b>constraints</b>: minLength/maxLength (cap prompt size), minimum/maximum, enum for allowed values, regex patterns for IDs.</li><li><b>additionalProperties: false</b>: reject unexpected fields.</li><li>array limits: maxItems to cap fan-out (e.g. at most 5 properties to compare).</li></ul>`,
          ['json-schema']),
        C('reject-unexpected', 'Why reject unexpected properties?',
          `If a client sends a field you did not ask for — say <span class="mono">"tenantId": "B"</span> or <span class="mono">"isAdmin": true</span> — silently accepting it is dangerous.`,
          `Unexpected fields can trigger mass-assignment vulnerabilities (a field binds to a model attribute it should not), hide client bugs (a misspelled <span class="mono">pageSise</span> silently ignored), and smuggle data into prompts or logs. Rejecting them with 400 and a clear error makes contracts explicit. For response schemas, the opposite convention applies: clients should <b>tolerate</b> new fields so the server can add data without breaking them.`,
          ['json-schema', 'tenant-isolation'],
          `Never accept identity or tenant fields from the request body. Derive tenant and user from the validated token.`),
        C('validate-where', 'Where validation happens',
          `Validate as early as possible, and again where meaning is checked.`,
          `Layered validation: the gateway can enforce size limits and schema basics; the service validates the full schema and then <b>semantic</b> rules (does Property A exist, is the user allowed to see it, is the date range sane). Fail fast with 400/422 and a precise error before spending money on retrieval or LLM calls.`,
          ['api-gateway', 'api-contract']),
        W('chatbot-trace', 'Trace: where validation sits in a chatbot request',
          'Step through the request and stop at the validation stage. Notice how cheap rejection is compared with everything that follows.'),
        C('pagination', 'Pagination',
          `Never return an unbounded list. Return a page of results and a way to get the next page.`,
          `<b>Offset pagination</b> (<span class="mono">?offset=200&limit=50</span>) is simple and allows jumping to page N, but gets slower on large offsets (the database still walks skipped rows) and can skip or repeat items when data changes between requests. <b>Cursor pagination</b> (<span class="mono">?after=opaqueCursor&limit=50</span>) encodes the position (e.g. last seen sort key + ID); it is stable under inserts and uses an index seek, but cannot jump to arbitrary pages. Always cap <span class="mono">limit</span>.`,
          ['pagination', 'index']),
        C('filter-sort', 'Filtering and sorting',
          `Let clients narrow results (<span class="mono">?status=active&city=Pune</span>) and choose order (<span class="mono">?sort=-updatedAt</span>), but only on fields you support.`,
          `Allow-list filterable and sortable fields so every supported combination has an index; arbitrary filters create unindexed full scans. Use a deterministic tiebreaker (e.g. ID) in sorts so pagination is stable.`,
          ['index', 'composite-index']),
        C('versioning', 'Versioning and evolution',
          `Clients you do not control will keep calling old shapes for months. Changing the contract must not break them.`,
          `Additive changes (new optional request fields, new response fields) are backward compatible if clients tolerate unknown fields. Breaking changes (removing/renaming fields, changing types or meaning, making a field required) need a new [[api-versioning|version]] — via URL (<span class="mono">/v2/</span>), header, or query parameter — plus a deprecation window, usage telemetry per version, and a sunset date.`,
          ['api-versioning']),
        C('errors', 'Errors are part of the contract',
          `A good error tells the caller what went wrong, which field, and whether retrying could help.`,
          `Consistent error body (e.g. RFC 9457 Problem Details): type, title, status, detail, and field-level errors, plus a correlation/trace ID. Distinguish client errors (don’t retry) from transient server errors (retry with backoff). Never leak stack traces or internal hostnames.`,
          ['status-codes', 'distributed-tracing']),
        NOTE('tip', 'Apply the same discipline to LLM tool calls: treat model-produced arguments as untrusted input and validate them against the tool schema before executing anything.'),
      ],
      quiz: [
        { q: 'A chat API accepts <span class="mono">{"question": "...", "tenantId": "B"}</span> and uses tenantId from the body to filter documents. What is the flaw?',
          options: ['tenantId should be an integer', 'Tenant identity must come from the validated token, and unexpected identity fields must be rejected', 'The question field needs a maxLength', 'The API should use PUT'],
          answer: 1, tag: 'tenant-isolation',
          why: 'Any user can type any tenantId. Identity and tenancy come from authenticated claims; the body must not be able to override them.',
          misconception: { 0: 'Type does not matter if the value is attacker-controlled.', 2: 'A size cap is good practice but does not fix the authorization flaw.', 3: 'The method is irrelevant to this vulnerability.' } },
        { q: 'Users paging through a fast-changing activity feed report seeing duplicate items. Which change fixes it?',
          options: ['Increase page size', 'Switch from offset to cursor pagination with a stable sort key and ID tiebreaker', 'Cache each page for an hour', 'Remove sorting'],
          answer: 1, tag: 'pagination',
          why: 'Inserts shift offsets, so items slide across page boundaries. A cursor anchored to the last-seen key is stable.',
          misconception: { 0: 'Larger pages reduce but do not eliminate the shift.', 2: 'Caching returns stale and still inconsistent pages.', 3: 'Without a deterministic order, pagination is undefined.' } },
        { q: 'Which change is backward compatible for existing clients that ignore unknown fields?',
          options: ['Renaming leaseEnd to leaseEndDate', 'Adding an optional response field leaseNotes', 'Making a previously optional request field required', 'Changing rate from number to string'],
          answer: 1, tag: 'api-versioning',
          why: 'Adding optional response fields is additive. The others break existing clients.',
          misconception: { 0: 'Clients reading leaseEnd break.', 2: 'Existing clients that omit the field now get 400s.', 3: 'Type changes break parsers.' } },
        { q: 'Why validate request schemas <b>before</b> running retrieval and the LLM?',
          options: ['Because LLMs cannot read JSON', 'Rejecting invalid requests early is cheap and prevents wasted cost, abuse and malformed downstream calls', 'Schemas make the LLM more accurate', 'Validation is only needed for responses'],
          answer: 1, tag: 'api-contract',
          why: 'Fail-fast validation protects expensive downstream resources and gives clear errors.',
          misconception: { 0: 'LLMs read JSON fine; that is not the point.', 2: 'Validation protects the system; it does not change model quality.', 3: 'Requests are the untrusted input; they need validation most.' } },
        { q: 'A client sends <span class="mono">pageSise=50</span> (typo). The API ignores it and returns the default 20. What would have caught this?',
          options: ['Longer timeouts', 'Rejecting unknown query parameters/properties with a 400 that names the field', 'A bigger default page size', 'Rate limiting'],
          answer: 1, tag: 'json-schema',
          why: 'Strict validation surfaces client bugs immediately instead of silently misbehaving.',
          misconception: { 0: 'Timeouts are unrelated to parameter parsing.', 2: 'That hides the bug differently.', 3: 'Rate limiting controls volume, not correctness of parameters.' } },
      ],
      teachback: { prompt: 'Describe the contract you would define for POST /chat in a multi-tenant property assistant, and what you would reject.',
        rubric: 'Required question with maxLength; optional conversationId format; propertyIds array with maxItems; additionalProperties false; tenant/user from token not body; semantic validation (property exists, user allowed); 400/422 error format with field and correlation ID; versioning strategy; validate LLM tool arguments similarly.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-rag-multitenant'], patternRefs: ['p-tenant-isolation'],
    },

    {
      id: 'l1-identity', level: 1, minutes: 30,
      title: 'Authentication, authorization and tokens',
      summary: 'Who are you, and what may you do? Identity providers, access tokens, JWTs, OAuth 2.0 and OpenID Connect, with Microsoft Entra ID as the running example.',
      prereqs: ['l1-contracts'],
      outcomes: [
        'You can separate authentication from authorization in any design.',
        'You can list what an API must check when validating a JWT.',
        'You can explain the OAuth 2.0 authorization code flow with PKCE and the client credentials flow.',
        'You can explain what OIDC adds on top of OAuth 2.0.',
      ],
      sections: [
        C('authn-authz', 'Authentication versus authorization',
          `[[authentication|Authentication]] answers “who are you?”. [[authorization|Authorization]] answers “are you allowed to do this?”. Logging in is authentication; being allowed to read Property A’s lease is authorization.`,
          `Authentication produces a verified identity (user or service). Authorization evaluates that identity plus attributes (roles, tenant, ownership, resource sensitivity) against a policy for a specific action on a specific resource. Authorization must happen for <b>every</b> resource access, not once at login — and in RAG systems, at retrieval time too.`,
          ['authentication', 'authorization']),
        C('idp', 'Identity providers',
          `Instead of every app storing passwords, an [[identity-provider|identity provider]] (IdP) handles sign-in and vouches for users by issuing tokens.`,
          `IdPs (Microsoft Entra ID, Okta, Auth0, Google) handle credentials, MFA, conditional access and federation. Applications trust the IdP’s signing keys, published at a well-known metadata/JWKS endpoint, and validate tokens locally without calling the IdP on each request.`,
          ['identity-provider']),
        C('tokens', 'Access tokens',
          `An [[access-token|access token]] is a short-lived pass the client presents with each request: “the IdP says this caller may use this API”.`,
          `Sent as <span class="mono">Authorization: Bearer &lt;token&gt;</span>. Bearer means whoever holds it can use it, so it must travel only over TLS, be short-lived (minutes to an hour), and never be logged. Refresh tokens (longer-lived, held by the client) obtain new access tokens without re-login.`,
          ['access-token']),
        C('jwt', 'JWTs and how to validate them',
          `A [[jwt|JWT]] is a token made of three parts — header, claims, signature. The claims say who the caller is and what the token is for; the signature proves the IdP issued it and nobody changed it.`,
          `To validate: <ul><li>verify the <b>signature</b> with the IdP’s published key, and only accept the expected algorithm (never “none”, never let the token pick an unexpected one);</li><li>check <b>iss</b> (issuer is your IdP/tenant), <b>aud</b> (audience is <i>your</i> API), <b>exp/nbf</b> (time window, small clock skew);</li><li>then read identity and authorization claims (subject, tenant ID, roles/scopes).</li></ul>JWT claims are base64-encoded, <b>not encrypted</b>: anyone can read them.`,
          ['jwt'],
          `Accepting a valid token issued for a <i>different</i> audience lets tokens meant for another app call yours. Always check aud.`),
        C('oauth', 'OAuth 2.0: delegated access',
          `[[oauth2|OAuth 2.0]] lets an app get permission to call an API without ever seeing the user’s password.`,
          `Main flows: <b>authorization code with PKCE</b> for user-facing apps (browser redirects to the IdP, user signs in, app exchanges a one-time code plus a PKCE verifier for tokens); <b>client credentials</b> for service-to-service calls with no user (the service authenticates as itself — on Azure, ideally with a [[managed-identity]] instead of a stored secret). Scopes describe what the app may do on the user’s behalf. The implicit flow is deprecated.`,
          ['oauth2', 'managed-identity']),
        C('oidc', 'OpenID Connect: identity on top of OAuth',
          `OAuth is about access; [[oidc|OpenID Connect]] adds login — a standard way to learn who the user is.`,
          `OIDC adds the ID token (a JWT for the client app describing the authenticated user), standard claims, a userinfo endpoint and discovery metadata. Rule of thumb: ID tokens are for the client to learn who signed in; access tokens are for APIs. An API should not accept ID tokens as access tokens.`,
          ['oidc', 'jwt']),
        {
          kind: 'steps', title: 'Authorization code flow with PKCE (user signs in to the chatbot)',
          steps: [
            { title: 'Start', text: 'The app creates a random code verifier and sends its hash (code challenge) while redirecting the browser to the IdP.' },
            { title: 'Sign in', text: 'The user authenticates at the IdP (password, MFA, conditional access). The app never sees the password.' },
            { title: 'Code returned', text: 'The IdP redirects back with a short-lived, single-use authorization code.' },
            { title: 'Exchange', text: 'The app exchanges the code plus the original verifier for tokens. PKCE ensures a stolen code is useless without the verifier.' },
            { title: 'Call the API', text: 'The app sends the access token as a bearer token. The API validates signature, issuer, audience and expiry locally.' },
            { title: 'Authorize each action', text: 'The API checks roles/tenant/ownership for each resource — e.g. that Property A belongs to the caller’s tenant.' },
          ],
        },
        W('chatbot-trace', 'Trace: authentication and authorization in a live request',
          'Step to the authentication stage and then the retrieval stage. Authentication happens once per request at the edge; authorization is enforced again where data is read.'),
        {
          kind: 'azure', title: 'On Azure: start from the problem',
          items: [
            { service: 'Microsoft Entra ID', problem: 'Users and services need a trusted identity, sign-in with MFA, and tokens your APIs can validate.', use: 'Workforce and B2B sign-in, app registrations defining API scopes and app roles, service identities, conditional access.', avoid: 'Building your own password store. For consumer-facing sign-up flows, use the external-identities offering rather than workforce tenants.' },
            { service: 'Managed identities', problem: 'Services need to call other Azure resources without storing secrets in config.', use: 'Container Apps, Functions or App Service calling Key Vault, Storage, Azure SQL, Azure OpenAI with Entra tokens.', avoid: 'Workloads running outside Azure (use workload identity federation instead of exporting secrets).' },
            { service: 'Azure API Management (validate-jwt policy)', problem: 'Reject unauthenticated or wrong-audience calls before they reach backends.', use: 'Coarse checks at the edge: signature, issuer, audience, required scopes.', avoid: 'Treating gateway checks as the only authorization — fine-grained, per-resource checks belong in the service.' },
          ],
        },
        C('authz-models', 'Authorization models',
          `Roles say what kind of user you are (“viewer”, “admin”). Attributes describe the specific situation (“tenant = A”, “document confidentiality = high”).`,
          `[[rbac|RBAC]] is simple and auditable; [[abac|ABAC]] handles fine-grained rules such as tenant ownership and document-level permissions. Real systems combine them: roles for coarse capability, attributes (tenant, owner, ACL) for each resource. Deep dive in Level 11.`,
          ['rbac', 'abac']),
      ],
      quiz: [
        { q: 'Your API accepts any JWT signed by your Entra tenant. A token issued for the internal HR app is replayed against your chatbot API and works. What check is missing?',
          options: ['Signature verification', 'Audience (aud) validation', 'Token expiry', 'TLS'],
          answer: 1, tag: 'jwt',
          why: 'The token is genuinely signed and unexpired — but for a different API. aud must equal your API’s identifier.',
          misconception: { 0: 'The signature is valid; it was issued by your IdP.', 2: 'The token may be well within its lifetime.', 3: 'TLS protects transport; it does not decide which tokens are acceptable.' } },
        { q: 'A user is authenticated and has the role “Analyst”. They request Property B, which belongs to another tenant. Where must the request be stopped?',
          options: ['At login', 'In an authorization check on the resource (tenant ownership) — and the data query itself must be tenant-scoped', 'Nowhere; Analysts can read everything', 'In the frontend by hiding Property B'],
          answer: 1, tag: 'authorization',
          why: 'Authorization is per action per resource. Defense in depth means the query also filters by tenant.',
          misconception: { 0: 'Login only establishes identity.', 2: 'A role does not grant cross-tenant access unless the policy says so.', 3: 'Hiding UI does not stop direct API calls.' } },
        { q: 'A background worker needs to call Azure OpenAI and Key Vault. Best way to authenticate?',
          options: ['Store an API key in an environment variable in the image', 'Use a managed identity and grant it least-privilege roles', 'Reuse a user’s access token', 'Disable authentication on private networks'],
          answer: 1, tag: 'managed-identity',
          why: 'Managed identities obtain Entra tokens without stored secrets; roles limit what the worker can do.',
          misconception: { 0: 'Secrets in images leak through registries and logs, and are hard to rotate.', 2: 'User tokens expire and grant the wrong identity for background work.', 3: 'Network location is not identity; zero trust requires authentication everywhere.' } },
        { q: 'What is true about JWT claims?',
          options: ['They are encrypted so only the API can read them', 'They are signed but readable by anyone holding the token', 'They cannot contain roles', 'They are validated by calling the IdP on every request'],
          answer: 1, tag: 'jwt',
          why: 'A standard signed JWT is encoded, not encrypted. Do not put secrets in claims.',
          misconception: { 0: 'Signing gives integrity, not confidentiality (unless you use JWE).', 2: 'Roles and scopes are common claims.', 3: 'Validation is local using the IdP’s cached public keys.' } },
        { q: 'Why is PKCE used in the authorization code flow?',
          options: ['To encrypt the access token', 'So an intercepted authorization code cannot be exchanged without the original verifier', 'To shorten token lifetime', 'To replace HTTPS'],
          answer: 1, tag: 'oauth2',
          why: 'PKCE binds the code to the client that started the flow.',
          misconception: { 0: 'PKCE does not encrypt tokens.', 2: 'Lifetime is set by the IdP policy.', 3: 'HTTPS is still required.' } },
      ],
      teachback: { prompt: 'Explain the difference between authentication and authorization using the chatbot request “What is the lease condition of Property A?” and say what the API checks.',
        rubric: 'IdP sign-in (OIDC) gives identity; access token (JWT) sent as bearer; API validates signature/alg, iss, aud, exp; derives user and tenant from claims; authorization per resource (tenant ownership, role, ACL); retrieval and SQL scoped by tenant; managed identity for service calls; never trust body-supplied identity.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-rag-multitenant'], patternRefs: ['p-tenant-isolation'],
    },

    {
      id: 'l1-edge', level: 1, minutes: 30,
      title: 'Gateways, load balancers, rate limits and backpressure',
      summary: 'Protect backends at the edge: API gateways, layer-4 and layer-7 load balancing, rate limiting, quotas, throttling and backpressure.',
      prereqs: ['l1-identity', 'l0-resources'],
      outcomes: [
        'You can explain what an API gateway does that a load balancer does not.',
        'You can compare token bucket, fixed window and sliding window rate limiting.',
        'You can distinguish rate limits, quotas, throttling and backpressure.',
        'You can design how a system says “not now” instead of collapsing.',
      ],
      sections: [
        C('lb', 'Load balancers',
          `A [[load-balancer|load balancer]] spreads incoming requests across many replicas and stops sending to ones that are unhealthy.`,
          `Layer 4 balancers route TCP/UDP connections by address and port (fast, protocol-agnostic). Layer 7 balancers understand HTTP: route by path or host, terminate TLS, apply WAF rules, and balance per request. Health probes remove failing instances. Algorithms (round robin, least connections, least outstanding requests) are covered in Level 3.`,
          ['load-balancer']),
        C('gateway', 'API gateways',
          `An [[api-gateway|API gateway]] is the front desk for your APIs: it checks credentials, enforces limits, routes to the right backend and records what happened.`,
          `Typical gateway responsibilities: token validation, rate limits and quotas per key/user/tenant, request size limits, routing and versioning, transformation, response caching, and analytics. It centralizes cross-cutting policy, but must not hold business logic or become the only authorization layer.`,
          ['api-gateway']),
        C('rate-limit', 'Rate limiting',
          `[[rate-limiting|Rate limiting]] caps how many requests a caller can make in a period — “100 requests per minute per user”.`,
          `Algorithms: <ul><li><b>Token bucket</b>: tokens refill at rate r up to capacity b; each request spends one. Allows short bursts up to b, then averages r. The most common choice.</li><li><b>Leaky bucket</b>: requests drain at a fixed rate; smooths output.</li><li><b>Fixed window</b>: count per calendar minute; simple but allows 2× bursts at window edges.</li><li><b>Sliding window</b>: weighted or log-based counting over a moving window; fairer edges.</li></ul>Distributed limits need shared counters (e.g. Redis) or approximate per-node limits.`,
          ['rate-limiting', 'http-429']),
        W('token-bucket', 'Experiment: token bucket under bursty traffic',
          'Change refill rate and bucket size, then send a burst. See which requests pass, which get 429, and how burst capacity differs from sustained rate.'),
        C('quota', 'Quotas and throttling',
          `A [[quota]] is a budget over a longer period (“10,000 calls per month”). [[throttling|Throttling]] is the act of slowing or rejecting requests that exceed a limit.`,
          `Quotas align with business plans and cost; rate limits protect capacity in the short term. Throttled responses should be <span class="mono">429 Too Many Requests</span> with a Retry-After header. Downstream providers throttle you too: Azure OpenAI enforces tokens-per-minute and requests-per-minute per deployment and returns 429 when you exceed them.`,
          ['quota', 'throttling', 'tpm', 'rpm']),
        C('backpressure', 'Backpressure',
          `[[backpressure|Backpressure]] is a slow part of the system telling faster parts to slow down, instead of silently piling up work until it collapses.`,
          `Mechanisms: bounded queues that reject or block when full, concurrency limits that return 429/503, TCP flow control, pull-based consumers, and propagating “I’m full” upstream. Without it, unbounded buffers grow, memory fills, latency explodes and timeouts trigger retries — making overload worse.`,
          ['backpressure', 'load-shedding'],
          `A queue without a bound is not backpressure; it just delays the collapse and adds latency.`),
        C('fairness', 'Per-tenant limits and fairness',
          `If one customer sends a flood, everyone else should not suffer.`,
          `Apply limits per tenant/key as well as globally; reserve capacity for priority traffic; consider weighted fair queuing. For LLM backends, budget tokens per tenant because one large-prompt tenant can consume the shared TPM quota.`,
          ['rate-limiting', 'tenant-isolation', 'bulkhead']),
        { kind: 'anatomy', title: 'Anatomy: the edge of a chatbot platform', caption: 'Each layer rejects different bad traffic as cheaply as possible.',
          nodes: [
            { id: 'client', label: 'Clients', kind: 'client', col: 0, row: 1, what: 'Web, mobile and partner integrations.' },
            { id: 'fd', label: 'Front Door + WAF', kind: 'edge', col: 1, row: 1, what: 'Global L7 entry with TLS termination and web application firewall.', why: 'Stops volumetric and common web attacks near the user.', fails: 'Over-broad WAF rules blocking real users.' },
            { id: 'apim', label: 'API Management', kind: 'gateway', col: 2, row: 1, what: 'Policy layer: JWT validation, rate limits per key/tenant, quotas, routing.', why: 'Rejects unauthenticated and abusive calls before they cost backend capacity.', monitor: 'Throttled requests, 401/403/429 by product and tenant.' },
            { id: 'aca', label: 'Chat API replicas', kind: 'service', col: 3, row: 1, what: 'Stateless API replicas with a concurrency limit each.', why: 'Applies semantic validation and per-request authorization.', fails: 'Unbounded in-flight requests exhaust pools.', scales: 'Autoscale on concurrent requests.' },
            { id: 'llm', label: 'Azure OpenAI', kind: 'llm', col: 4, row: 1, what: 'Model deployment with TPM/RPM quota.', fails: '429 when quota is exceeded.', monitor: 'Tokens/min used, 429 rate, latency.' },
          ],
          edges: [['client', 'fd', 'HTTPS'], ['fd', 'apim'], ['apim', 'aca', 'within limits'], ['aca', 'llm', 'bounded']] },
        {
          kind: 'azure', title: 'On Azure: start from the problem',
          items: [
            { service: 'Azure API Management', problem: 'Many clients and APIs need consistent authentication, rate limits, quotas, versioning and analytics.', use: 'Central API front door: validate-jwt, rate-limit-by-key and quota-by-key policies, products/subscriptions, and a gateway in front of Azure OpenAI to spread or meter token usage.', avoid: 'Placing business logic in policies, or adding it for a single internal API with no policy needs.' },
            { service: 'Application Gateway', problem: 'Regional HTTP load balancing with TLS termination and a WAF.', use: 'Path-based routing within one region, WAF in front of web apps.', avoid: 'Global multi-region routing (use Front Door).' },
            { service: 'Azure Front Door', problem: 'Global users need a nearby entry point, failover across regions, caching and WAF.', use: 'Multi-region apps and static/content acceleration.', avoid: 'Purely internal or private-network traffic.' },
          ],
        },
      ],
      quiz: [
        { q: 'A tenant runs a batch job that sends 50k chat requests in a minute. Other tenants see 429s from Azure OpenAI. Best structural fix?',
          options: ['Increase every client’s retry count', 'Per-tenant rate limits and token budgets at the gateway, plus a separate (bulkheaded) path or deployment for batch work', 'Disable 429 handling', 'Add more API replicas'],
          answer: 1, tag: 'rate-limiting',
          why: 'The shared LLM quota is the contended resource. Per-tenant limits and isolation protect other tenants.',
          misconception: { 0: 'More retries add load to the exhausted quota.', 2: 'Ignoring 429s just turns them into failures elsewhere.', 3: 'Replicas do not add LLM quota; they increase pressure on it.' } },
        { q: 'With a fixed one-minute window of 100 requests, why can a client make ~200 requests in two seconds?',
          options: ['The limit is per second', 'It can send 100 at 0:59 and 100 at 1:00 — two windows', 'Fixed windows refill continuously', 'Gateways ignore limits under load'],
          answer: 1, tag: 'rate-limiting',
          why: 'Window boundaries allow double bursts. Sliding windows or token buckets smooth this.',
          misconception: { 0: 'The limit is per minute; the issue is the boundary.', 2: 'Continuous refill describes a token bucket.', 3: 'The gateway enforces the configured algorithm correctly; the algorithm permits it.' } },
        { q: 'What distinguishes backpressure from simply adding a large queue?',
          options: ['Nothing — they are the same', 'Backpressure bounds work in progress and signals upstream to slow down or stop; an unbounded queue absorbs load until memory or latency fails', 'Queues are always faster', 'Backpressure only applies to TCP'],
          answer: 1, tag: 'backpressure',
          why: 'Backpressure makes overload visible and controlled; unbounded buffering hides it until it fails catastrophically.',
          misconception: { 0: 'A queue may be part of backpressure only if bounded and signaling.', 2: 'Speed is not the difference; boundedness and signaling are.', 3: 'TCP flow control is one example; the principle applies at every layer.' } },
        { q: 'Which response should a rate-limited request receive?',
          options: ['500 with a stack trace', '429 with a Retry-After header', '200 with an empty body', '404'],
          answer: 1, tag: 'http-429',
          why: '429 tells the client the condition is temporary and caller-specific; Retry-After tells it when to come back.',
          misconception: { 0: 'It is not a server error, and stack traces leak internals.', 2: 'Silently returning empty data is misleading.', 3: 'The resource exists.' } },
        { q: 'Why keep fine-grained authorization in the service even if the gateway validates JWTs?',
          options: ['Gateways cannot read JWTs', 'The gateway can check the token is valid, but only the service knows whether this user may access this specific resource', 'It is faster', 'Gateways are always optional'],
          answer: 1, tag: 'authorization',
          why: 'Resource-level decisions (tenant ownership, document ACLs) need domain data the gateway does not have.',
          misconception: { 0: 'Gateways commonly validate JWTs.', 2: 'Speed is not the reason.', 3: 'The issue is responsibility, not optionality.' } },
      ],
      teachback: { prompt: 'Explain how you would stop one noisy tenant from degrading a shared AI chatbot for everyone.',
        rubric: 'Gateway auth then per-tenant rate limits (token bucket) and token quotas; 429 + Retry-After; backpressure via bounded concurrency in service; bulkhead/separate deployment for batch; monitor per-tenant usage; LLM TPM/RPM as shared bottleneck; replicas do not add quota.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-llm-inference', 'case-flashsale'], patternRefs: ['p-rate-limiting', 'p-backpressure-shedding', 'p-admission-control', 'p-bulkheads'],
    },

    {
      id: 'l1-resilience', level: 1, minutes: 35,
      title: 'Idempotency, timeouts, retries and circuit breakers',
      summary: 'Make calls survivable: idempotent operations, timeouts and deadlines, retries with exponential backoff and jitter, circuit breakers and graceful degradation.',
      prereqs: ['l1-edge'],
      outcomes: [
        'You can design an idempotency-key mechanism for a create operation.',
        'You can explain why every network call needs a timeout and how deadlines propagate.',
        'You can explain why jitter prevents synchronized retry waves.',
        'You can describe circuit breaker states and when they open.',
      ],
      sections: [
        C('idempotency', 'Idempotency and duplicate requests',
          `If a request is sent twice, the result should be the same as sending it once. Then a client can always safely retry.`,
          `Duplicates come from client retries after timeouts, double-clicks, at-least-once message delivery and LLM agents re-calling tools. Implement with an [[idempotency-key]]: the client generates a unique key per logical operation; the server atomically records the key with the operation’s result (usually in the same transaction as the side effect); repeats return the stored result; concurrent duplicates wait or get 409. Keys expire after a retention window.`,
          ['idempotency', 'idempotency-key'],
          `Checking “does the key exist?” and then writing in two separate steps races. Use a unique constraint or atomic insert.`),
        C('timeouts', 'Timeouts and deadlines',
          `Never wait forever. A [[timeout]] says “if this call has not answered in 2 seconds, give up and do something else.”`,
          `Without timeouts, a slow dependency holds threads and connections indefinitely, exhausting pools (the “slow but not dead” failure). Set timeouts per call based on the dependency’s p99, and propagate a <b>deadline</b> (remaining time budget) through the call chain so downstream work stops when the user has already given up. Distinguish connect timeout from read/response timeout; for streaming LLMs also set a time-to-first-token timeout.`,
          ['timeout', 'ttft']),
        C('retries', 'Retries',
          `Many failures are temporary — a dropped packet, a brief overload. Trying again often works.`,
          `Retry only <b>transient</b> errors (timeouts, 503, 429, connection resets) and only <b>idempotent</b> operations (or ones protected by idempotency keys). Cap attempts (e.g. 2–3), cap total time within the deadline, and retry at only one layer — retries at every layer multiply: 3 layers × 3 attempts = up to 27 calls to the bottom service.`,
          ['retry', 'retry-storm']),
        C('backoff-jitter', 'Exponential backoff and jitter',
          `After a failure, wait a bit before retrying, and wait longer each time. Add randomness so thousands of clients do not all retry at the same instant.`,
          `[[exponential-backoff|Exponential backoff]]: delay = base × 2<sup>attempt</sup>, capped. [[jitter|Jitter]] randomizes the delay (e.g. “full jitter”: random between 0 and the backoff value) to break synchronization. Without jitter, clients that failed together retry together, producing periodic waves that re-overload a recovering service.`,
          ['exponential-backoff', 'jitter']),
        W('retry-jitter', 'Experiment: retry waves with and without jitter',
          'Fail a dependency for a few seconds, then let it recover. Compare immediate retries, exponential backoff, and backoff with jitter. Watch the load on the recovering service.'),
        C('circuit-breaker', 'Circuit breakers',
          `A [[circuit-breaker|circuit breaker]] stops calling a dependency that is clearly failing, so you fail fast instead of piling up waits — and gives the dependency room to recover.`,
          `States: <b>closed</b> (calls flow; failures counted over a window), <b>open</b> (calls fail immediately or use a fallback for a cool-down period), <b>half-open</b> (a few trial calls; success closes the breaker, failure re-opens it). Trip on error rate or slow-call rate above a threshold with a minimum request volume. Breakers protect the caller’s resources and reduce load on the sick dependency.`,
          ['circuit-breaker']),
        {
          kind: 'steps', title: 'Circuit breaker lifecycle',
          steps: [
            { title: 'Closed', text: 'Normal. Calls pass through; the breaker tracks failure and slow-call rates over a sliding window.' },
            { title: 'Trips open', text: 'Failure rate exceeds the threshold (with enough samples). Further calls fail immediately or go to a fallback.' },
            { title: 'Cool down', text: 'No calls reach the dependency for the wait period, freeing threads and giving it time to recover.' },
            { title: 'Half-open', text: 'A limited number of probe calls are allowed through.' },
            { title: 'Close or re-open', text: 'Probes succeed → closed. Probes fail → open again for another cool-down.' },
          ],
        },
        C('degradation', 'Error handling and graceful degradation',
          `When part of the system fails, give users a smaller but useful answer instead of an error page.`,
          `[[graceful-degradation|Graceful degradation]] examples for a property chatbot: if the reranker is down, return vector results without reranking; if the LLM is throttled, answer structured questions (rate, lease end date) directly from SQL and say the narrative summary is delayed; if the primary model is unavailable, route to a smaller fallback model with a notice. Decide degradations in advance and test them.`,
          ['graceful-degradation', 'model-routing']),
        C('error-handling', 'Errors that help',
          `Errors should say what failed, whether retrying might help, and how to find it in the logs.`,
          `Map internal failures to clear status codes (400/409/422 for caller errors; 429/503 with Retry-After for overload; 504 for upstream timeouts). Include a correlation ID. Log the cause with context; never expose stack traces or internal hostnames to clients.`,
          ['status-codes', 'distributed-tracing']),
      ],
      quiz: [
        { q: 'An LLM agent calls the <span class="mono">createWorkOrder</span> tool, the call times out, and the agent calls it again. Two work orders appear. What prevents this?',
          options: ['A longer tool timeout', 'An idempotency key per logical operation, stored atomically with the result so the repeat returns the original order', 'Telling the model not to retry', 'Rate limiting the agent'],
          answer: 1, tag: 'idempotency-key',
          why: 'Timeouts make it impossible to know whether the first call succeeded. The server must deduplicate.',
          misconception: { 0: 'Longer timeouts reduce but never eliminate ambiguous outcomes.', 2: 'Prompts are not guarantees; models and networks still retry.', 3: 'Rate limits restrict volume, not duplicates.' } },
        { q: 'Three service layers each retry 3 times on failure. The bottom service goes down. How many calls can one user request generate against it?',
          options: ['3', '9', '27', '1'],
          answer: 2, tag: 'retry-storm',
          why: 'Retries multiply across layers: 3 × 3 × 3 = 27. Retry at one layer and use budgets.',
          misconception: { 0: 'That counts only one layer.', 1: 'That counts two layers.', 3: 'Retries add calls by design.' } },
        { q: 'A dependency recovers after an outage, then immediately collapses again in regular waves. What is most likely missing?',
          options: ['TLS', 'Jitter on retry backoff', 'Larger database', 'A CDN'],
          answer: 1, tag: 'jitter',
          why: 'Clients that failed together retry together. Randomized delays spread the load.',
          misconception: { 0: 'Encryption has no effect on retry timing.', 2: 'The dependency is the target; the issue is synchronized load.', 3: 'A CDN does not change client retry behavior for API calls.' } },
        { q: 'What does an open circuit breaker do?',
          options: ['Sends all calls with extra retries', 'Fails calls immediately or uses a fallback without calling the dependency, until a cool-down ends', 'Permanently disables the dependency', 'Encrypts requests'],
          answer: 1, tag: 'circuit-breaker',
          why: 'Open means fail fast to protect the caller and the struggling dependency; half-open probes test recovery.',
          misconception: { 0: 'That is the opposite of what a breaker does.', 2: 'It transitions to half-open after cool-down.', 3: 'Breakers are about failure handling, not encryption.' } },
        { q: 'A vector search dependency is not down but now takes 8 s instead of 80 ms. Your API threads are all stuck waiting. What should have limited the damage?',
          options: ['A timeout aligned to the dependency’s normal p99 plus a slow-call circuit breaker and fallback', 'Bigger instances', 'Removing the dependency', 'Increasing the thread pool to unlimited'],
          answer: 0, tag: 'timeout',
          why: 'Slow-but-alive dependencies are worse than dead ones without timeouts. Timeouts free resources; slow-call breakers fail fast.',
          misconception: { 1: 'Bigger CPUs do nothing for waiting threads.', 2: 'Not a realistic resilience strategy.', 3: 'Unlimited threads just move exhaustion to memory and the dependency.' } },
      ],
      teachback: { prompt: 'Explain how timeouts, retries with jitter, idempotency and circuit breakers must work together — and what goes wrong if any one is missing.',
        rubric: 'Timeouts free resources and bound waits; retries only for transient errors with caps and single layer; exponential backoff + jitter avoids synchronized waves; idempotency makes retries safe for side effects; circuit breakers stop hammering a failing dependency and fail fast; graceful degradation; missing any piece → pool exhaustion, retry storms, duplicates.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-payments-idempotency', 'case-chaos-monkey'], patternRefs: ['p-idempotency', 'p-circuit-breaker-retries', 'p-graceful-degradation'],
    },

    {
      id: 'l1-connections-streaming', level: 1, minutes: 30,
      title: 'Connection pools, async APIs and streaming',
      summary: 'Reuse expensive connections, design APIs for long-running work, and stream results with SSE, WebSockets or polling.',
      prereqs: ['l1-resilience', 'l0-execution'],
      outcomes: [
        'You can explain why connection reuse matters and how pool exhaustion appears.',
        'You can design an asynchronous request-reply API for long-running jobs.',
        'You can choose between SSE, WebSockets and polling for a given feature.',
        'You can explain time to first token and why streaming improves perceived latency.',
      ],
      sections: [
        C('conn-cost', 'Connections are expensive to open',
          `Opening a new connection costs round trips (TCP + TLS) and work on both sides. Reusing an open connection skips all of that.`,
          `HTTP clients keep connections alive and pool them per host; HTTP/2 multiplexes many requests over one connection. Database connections are even more expensive (authentication, session setup, server memory per connection). Creating a new client object per request — a common bug — defeats pooling and can exhaust sockets (ephemeral port exhaustion) under load.`,
          ['connection-pool', 'tcp', 'tls']),
        C('keepalive-h2', 'Keep-alive and HTTP/2 multiplexing',
          `Keep-alive leaves a connection open after a response so the next request can reuse it. HTTP/2 goes further: many requests share one connection at the same time.`,
          `HTTP/1.1 keep-alive reuses connections but each carries one request at a time, so clients open several per host. HTTP/2 multiplexes concurrent streams over one TCP+TLS connection with header compression, which cuts handshakes and connection counts — useful for calls to LLM and search APIs. Servers and gateways cap concurrent streams per connection, so very high fan-out still needs several connections.`,
          ['http', 'connection-pool']),
        C('pools', 'Connection pools',
          `A [[connection-pool|connection pool]] keeps a fixed set of open connections and lends them to requests. When all are in use, the next request waits.`,
          `Pool size caps concurrency to that dependency. Size it with Little’s Law: needed ≈ request rate × time each request holds a connection. Watch pool wait time and timeouts — not just active count. Hold connections only for the query, never across an LLM call. Remember total connections = replicas × pool size, which must fit the database’s limit.`,
          ['connection-pool', 'little-law'],
          `Holding a DB connection while waiting 5 s for the LLM turns a 20 ms need into a 5 s hold — a 250× cut in effective pool capacity.`),
        W('pool-exhaustion', 'Experiment: exhaust a connection pool',
          'Increase traffic and how long each request holds a connection. Watch requests start waiting for connections while the database itself is lightly loaded.'),
        C('async-api', 'Asynchronous API design',
          `Some work takes minutes (ingesting a 300-page lease, re-embedding a portfolio). Don’t make the client hold a connection that long.`,
          `Async request-reply: <span class="mono">POST /ingestions</span> validates and returns <span class="mono">202 Accepted</span> with a job ID and a status URL; work goes onto a queue; the client polls <span class="mono">GET /ingestions/{id}</span> or receives a webhook/event when done. Make job creation idempotent, include progress and failure detail, and expire old jobs.`,
          ['message-queue', 'idempotency']),
        CMP('cmp-queue-immediate'),
        C('streaming', 'Streaming responses',
          `Instead of waiting 8 seconds for a full LLM answer, send words as they are generated. The user sees progress within a second.`,
          `Streaming improves perceived latency: [[ttft|time to first token]] drops to retrieval + prompt processing time, while total generation time is unchanged. It also holds the connection (and any per-request resources) for the full duration, so servers need async I/O and enough connection capacity. Validate or filter content incrementally if safety checks are required, or buffer critical parts.`,
          ['ttft', 'sse']),
        C('transports', 'Polling, SSE and WebSockets',
          `Three ways for a browser to get updates: ask repeatedly ([[polling]]), keep one response open and receive events ([[sse|SSE]]), or open a two-way channel ([[websocket|WebSocket]]).`,
          `Polling is simple and works everywhere but wastes requests and adds delay. Long polling holds the request until data exists. SSE is one-directional over plain HTTP with automatic reconnection — the natural fit for LLM token streams. WebSockets are full-duplex and suit interactive, bidirectional sessions but need upgrade-aware infrastructure and connection-aware routing.`,
          ['polling', 'sse', 'websocket']),
        W('transport-compare', 'Animation: polling vs SSE vs WebSocket',
          'Watch messages and wasted requests for each transport as the update frequency changes.'),
        CMP('cmp-sse-websocket'),
        NOTE('warn', 'Proxies and gateways that buffer responses silently break streaming: the user gets everything at the end. Verify buffering is disabled end to end and measure time to first byte at the client.'),
      ],
      quiz: [
        { q: 'A chat API holds a database connection from the start of the request until the LLM finishes (~6 s). The pool has 20 connections per replica. What is the maximum request rate per replica before requests wait for connections?',
          options: ['~3.3 req/s', '~20 req/s', '~120 req/s', 'Unlimited'],
          answer: 0, tag: 'connection-pool',
          why: '20 connections / 6 s hold ≈ 3.3 req/s. Releasing the connection after the 20 ms query raises this enormously.',
          misconception: { 1: 'That assumes a 1 s hold.', 2: 'That multiplies instead of divides.', 3: 'Pools are finite by design.' } },
        { q: 'Under load, a service shows thousands of sockets in TIME_WAIT and intermittent connection errors to a downstream API. Likely cause?',
          options: ['The downstream API is too fast', 'A new HTTP client (and connection) is created per request instead of reusing a pooled client', 'TLS is disabled', 'The database is down'],
          answer: 1, tag: 'connection-pool',
          why: 'Per-request clients open and close connections constantly, exhausting ephemeral ports and paying handshakes every time.',
          misconception: { 0: 'Speed does not create TIME_WAIT buildup.', 2: 'TLS state does not cause port exhaustion.', 3: 'The symptom is on the outbound HTTP path.' } },
        { q: 'Uploading and indexing a 400-page document takes ~3 minutes. Best API shape?',
          options: ['Synchronous POST that returns after indexing', 'POST returns 202 with a job ID; work is queued; client polls status or gets a notification', 'WebSocket that streams the PDF back', 'GET with the document in the query string'],
          answer: 1, tag: 'message-queue',
          why: 'Long work should not hold a request open; async request-reply with an idempotent job decouples the client from processing time.',
          misconception: { 0: 'Gateways and clients time out; retries would duplicate work.', 2: 'Bidirectional streaming adds nothing here.', 3: 'GET must not carry large payloads or create side effects.' } },
        { q: 'Why does streaming reduce perceived latency for LLM answers?',
          options: ['It makes the model generate faster', 'The first tokens reach the user after retrieval and prompt processing instead of after the full generation', 'It reduces token cost', 'It removes the need for authentication'],
          answer: 1, tag: 'ttft',
          why: 'Total time is the same; time to first token is what users perceive as responsiveness.',
          misconception: { 0: 'Generation speed is unchanged.', 2: 'You pay for the same tokens.', 3: 'Streams still require authentication.' } },
        { q: 'For streaming chatbot answers to a browser through an API gateway, which transport is usually the best default?',
          options: ['Short polling every 100 ms', 'Server-Sent Events', 'Raw TCP sockets', 'Email'],
          answer: 1, tag: 'sse',
          why: 'Server-to-client, plain HTTP, gateway friendly, automatic reconnection.',
          misconception: { 0: 'Wasteful and adds latency.', 2: 'Browsers cannot open raw TCP sockets.', 3: 'Not a real-time transport.' } },
      ],
      teachback: { prompt: 'Explain how you would handle both a quick chat answer and a 3-minute document ingestion in the same API — connections, transport and job design.',
        rubric: 'Chat: SSE streaming, TTFT, async I/O, release DB connection after query, pooled HTTP clients; Ingestion: 202 + job ID + queue + idempotent job + status polling/webhook; pool sizing via Little’s Law; replicas × pool vs DB limit; disable proxy buffering.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-llm-inference'], patternRefs: ['p-connection-pooling', 'p-async-parallel', 'p-queue-leveling'],
    },

    {
      id: 'l1-azure-backend', level: 1, minutes: 30,
      title: 'Azure building blocks for backends',
      summary: 'Map backend problems to Azure services — Container Apps, App Service, Functions, Service Bus, Redis, Key Vault, Monitor — and secure the API with tenant isolation from the start.',
      prereqs: ['l1-connections-streaming', 'l1-identity'],
      outcomes: [
        'You can choose a compute service from workload characteristics.',
        'You can explain what Service Bus, Redis and Key Vault each solve.',
        'You can sketch a secure Azure reference architecture for a chatbot API.',
        'You can name the telemetry you need from day one.',
      ],
      sections: [
        C('problem-first', 'Problems first, products second',
          `Every Azure service exists to solve a specific engineering problem. If you can name the problem, choosing the service is easy — and you avoid adding services you do not need.`,
          `Typical problems: run my code (compute), protect and meter my APIs (gateway), decouple slow work (messaging), avoid repeating expensive reads (cache), keep secrets out of code (secret store), know what is happening (observability). Each product also brings limits, pricing and operational duties that must be checked against current docs.`,
          ['api-gateway', 'message-queue', 'redis', 'key-vault']),
        {
          kind: 'azure', title: 'Compute: where does my code run?',
          items: [
            { service: 'Azure Container Apps', problem: 'Run containerized APIs and workers that scale with traffic without managing Kubernetes.', use: 'Stateless HTTP APIs and background workers; scale rules on HTTP concurrency, CPU or queue length (KEDA-based); can scale to zero; revisions for traffic splitting.', avoid: 'Workloads that need deep Kubernetes control (custom operators, node-level tuning) — consider AKS.' },
            { service: 'Azure App Service', problem: 'Host a web app or API with minimal platform work.', use: 'Traditional web apps and APIs, deployment slots for staged swaps, built-in auth integration.', avoid: 'Event-driven scale-to-zero workers or heavy queue-driven background processing.' },
            { service: 'Azure Functions', problem: 'Run small pieces of code in response to events (a queue message, a blob upload, a timer).', use: 'Glue and event handlers with spiky, short work; Consumption/Flex plans bill per execution.', avoid: 'Latency-sensitive APIs that cannot tolerate cold starts on consumption plans, or long-running CPU-heavy jobs.' },
          ],
        },
        {
          kind: 'azure', title: 'Messaging, caching, secrets and visibility',
          items: [
            { service: 'Azure Service Bus', problem: 'Slow or failure-prone work must not block users, and messages must not be lost.', use: 'Queues and topics for commands; competing consumers; sessions for ordering; duplicate detection; dead-lettering; scheduled delivery.', avoid: 'High-volume telemetry or replayable event history — use Event Hubs.' },
            { service: 'Azure Cache for Redis', problem: 'The same expensive data is read repeatedly; sessions and rate-limit counters need shared fast state.', use: 'Cache-aside for hot reads, distributed rate limiting, short-lived session or conversation state, semantic cache lookups.', avoid: 'As the only copy of important data, or for caching authorization decisions without short TTLs.' },
            { service: 'Azure Key Vault', problem: 'Secrets, keys and certificates must not live in code, images or config files.', use: 'Store secrets and certificates; access via managed identity; rotation; audit logs.', avoid: 'Fetching on every request (cache in memory with refresh) or storing non-secret config.' },
            { service: 'Azure Monitor + Application Insights', problem: 'You cannot fix what you cannot see: latency, errors, dependencies and traces across services.', use: 'Request/dependency telemetry, distributed traces via OpenTelemetry, logs, metrics, alerts and dashboards.', avoid: 'Logging full prompts and responses with PII without redaction and retention controls.' },
          ],
        },
        C('ref-arch', 'A minimal reference architecture',
          `Start small: one entry point, one stateless API, the stores you need, and observability. Add pieces only when a requirement asks for them.`,
          `Front Door (global entry + WAF) → API Management (JWT validation, per-tenant limits) → Container Apps API (stateless, autoscaled on concurrency) → Azure SQL / Cosmos DB, Azure AI Search, Azure OpenAI; Service Bus + worker for ingestion; Redis for cache; Key Vault and managed identities for secrets; Application Insights for traces. Private endpoints keep data-plane traffic off the public internet.`,
          ['managed-identity', 'opentelemetry']),
        { kind: 'anatomy', title: 'Anatomy: a secure chatbot API on Azure', caption: 'Click components to see their role and failure modes.',
          nodes: [
            { id: 'user', label: 'User', kind: 'client', col: 0, row: 1 },
            { id: 'apim', label: 'API Management', kind: 'gateway', col: 1, row: 1, what: 'Validates JWTs from Entra ID, applies per-tenant rate limits.', fails: 'Policy misconfiguration blocks traffic or lets wrong-audience tokens in.' },
            { id: 'api', label: 'Chat API', kind: 'service', sub: 'Container Apps', col: 2, row: 1, what: 'Stateless API that authorizes per resource and orchestrates retrieval and generation.', scales: 'HTTP concurrency scale rule; min replicas > 0 to avoid cold starts.', monitor: 'Requests, dependency calls, in-flight count via Application Insights.' },
            { id: 'redis', label: 'Redis cache', kind: 'cache', col: 2, row: 0, what: 'Hot property facts and rate-limit counters.', fails: 'Stale data after updates; stampede when hot keys expire.' },
            { id: 'sql', label: 'Azure SQL', kind: 'db', col: 3, row: 0, what: 'Authoritative property, rate and lease records.', fails: 'Connection limit reached when replicas scale out.' },
            { id: 'search', label: 'Azure AI Search', kind: 'search', col: 3, row: 1, what: 'Hybrid (keyword + vector) index over lease documents with tenant filter fields.', fails: 'Missing tenant filter leaks documents across tenants.' },
            { id: 'aoai', label: 'Azure OpenAI', kind: 'llm', col: 3, row: 2, what: 'Model deployment with TPM/RPM quota.', fails: '429 throttling under load.' },
            { id: 'kv', label: 'Key Vault', kind: 'security', col: 1, row: 2, what: 'Secrets and certificates, accessed with managed identity.' },
            { id: 'ai', label: 'App Insights', kind: 'obs', col: 2, row: 2, what: 'Traces, metrics and logs with correlation IDs across every call.' },
          ],
          edges: [['user', 'apim', 'HTTPS + JWT'], ['apim', 'api', 'tenant-limited'], ['api', 'redis'], ['api', 'sql', 'tenant-scoped'], ['api', 'search', 'filtered'], ['api', 'aoai', 'prompt'], ['api', 'kv', 'MI', 'async'], ['api', 'ai', 'telemetry', 'async']] },
        C('compute-choice', 'Choosing compute by workload shape',
          `The right place to run code depends on how the work arrives and how long it runs, not on which service is newest.`,
          `Ask: is it a long-running HTTP API or event-triggered snippets? Must it scale to zero? Can it tolerate a cold start? Does it need custom networking or Kubernetes features? Long-lived, latency-sensitive APIs fit Container Apps or App Service with minimum replicas above zero; bursty event handlers fit Functions or queue-scaled Container Apps jobs; platform teams needing full Kubernetes control choose AKS.`,
          ['cold-start', 'autoscaling', 'orchestration']),
        C('private-network', 'Network boundaries and private endpoints',
          `Your database and model endpoints should not be reachable from the whole internet, even with good passwords.`,
          `Private endpoints give PaaS services (Azure SQL, Storage, AI Search, Azure OpenAI, Key Vault) private IP addresses inside your virtual network, and public access can be disabled. Combine network isolation with identity ([[managed-identity]]) — network location alone is not authorization ([[zero-trust]]).`,
          ['zero-trust', 'managed-identity']),
        C('tenant-isolation-intro', 'API security and tenant isolation from day one',
          `In a multi-tenant product, the worst bug is one customer seeing another customer’s data. Design the boundary before writing features.`,
          `Derive tenant ID from the validated token; scope every query, cache key, search filter and queue message by tenant; never accept tenant from the request body; include tenant in logs and traces; test isolation explicitly (User A tries to read User B’s resources). Choose an isolation model (shared tables with tenant column + [[row-level-security]], schema per tenant, database per tenant) by risk and cost. Deep dive in Level 11.`,
          ['tenant-isolation', 'row-level-security'],
          `Cache keys without a tenant component are a classic cross-tenant leak: “property:A:summary” computed for tenant A is served to tenant B.`),
        W('chatbot-load', 'Simulator: the same architecture under load',
          'Use the simulator to see which Azure component becomes the bottleneck first — usually the model quota or the database connections, not Container Apps CPU.'),
        C('observe', 'Observability you need on day one',
          `If you can’t see where time goes, every incident becomes guesswork.`,
          `Minimum: request rate, error rate and latency percentiles per endpoint; dependency latency and failures (SQL, Search, OpenAI, Redis); in-flight requests and pool waits; LLM tokens per request and 429 counts; a trace ID propagated through every hop ([[opentelemetry|OpenTelemetry]] → Application Insights); alerts on [[slo|SLO]] burn, not raw CPU.`,
          ['distributed-tracing', 'opentelemetry', 'slo']),
      ],
      quiz: [
        { q: 'A queue-driven document ingestion worker should run zero instances overnight and scale with backlog. Best compute choice?',
          options: ['App Service with a fixed instance count', 'Container Apps (or Functions) with a scale rule on queue length, able to scale to zero', 'A single large VM', 'Azure Front Door'],
          answer: 1, tag: 'autoscaling',
          why: 'Event-driven scaling on queue depth matches the workload and saves cost when idle.',
          misconception: { 0: 'Fixed instances pay for idle time and don’t follow backlog.', 2: 'No scaling, single point of failure.', 3: 'Front Door is an entry point, not compute.' } },
        { q: 'A cache key <span class="mono">summary:property-A</span> is shared by all tenants. What risk does this create?',
          options: ['Cache stampede', 'Cross-tenant data leakage when tenants have different data or permissions for Property A', 'Higher latency', 'Key Vault outages'],
          answer: 1, tag: 'tenant-isolation',
          why: 'Every cache key for tenant-scoped data must include the tenant (and often the permission scope).',
          misconception: { 0: 'Stampedes concern expiry of hot keys, not isolation.', 2: 'Shared keys usually lower latency — the problem is correctness.', 3: 'Unrelated service.' } },
        { q: 'Where should the Container App get its Azure OpenAI credentials?',
          options: ['A key baked into the container image', 'A managed identity granted an appropriate role on the Azure OpenAI resource', 'The user’s browser', 'A shared admin account password'],
          answer: 1, tag: 'managed-identity',
          why: 'Managed identity avoids stored secrets and supports least privilege and auditing.',
          misconception: { 0: 'Images are copied, cached and inspected; keys leak and rotation is painful.', 2: 'Clients must never hold backend credentials.', 3: 'Shared admin credentials violate least privilege.' } },
        { q: 'Which alert best reflects user impact for the chat API?',
          options: ['CPU above 70%', 'Error budget burn rate on an SLO for successful responses within the latency target', 'Number of replicas', 'Disk usage'],
          answer: 1, tag: 'slo',
          why: 'SLO burn alerts fire on what users experience; CPU often stays low in I/O-bound outages.',
          misconception: { 0: 'CPU can be low during severe latency problems.', 2: 'Replica count is a capacity signal, not impact.', 3: 'Rarely relevant to an API’s user experience.' } },
        { q: 'You need long, replayable event history consumed by analytics and search indexing. Which service fits better than Service Bus queues?',
          options: ['Key Vault', 'Event Hubs (partitioned event stream)', 'Redis', 'App Service'],
          answer: 1, tag: 'event-stream',
          why: 'Event Hubs retains a partitioned log that independent consumer groups can read and replay.',
          misconception: { 0: 'Key Vault stores secrets.', 2: 'Redis is not a durable replayable log for this purpose.', 3: 'App Service is compute.' } },
      ],
      teachback: { prompt: 'Walk through an Azure architecture for a multi-tenant property chatbot and justify each service by the problem it solves.',
        rubric: 'Front Door/APIM for entry, JWT, per-tenant limits; Container Apps stateless API scaled on concurrency; SQL for authoritative data; AI Search hybrid with tenant filters; Azure OpenAI with quota awareness; Service Bus + worker for ingestion; Redis cache with tenant-scoped keys; Key Vault + managed identity; App Insights/OTel; private endpoints; tenant from token.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-rag-multitenant', 'case-llm-inference'], patternRefs: ['p-horizontal-stateless', 'p-caching', 'p-tenant-isolation', 'p-observability-slo'],
    },

    /* ---------------------------------------------------------------- L2 */
    {
      id: 'l2-thinking-at-scale', level: 2, minutes: 35,
      title: 'How systems handle millions of users',
      summary: 'Think like an owner of a large system: separate read and write paths, estimate capacity with explicit assumptions, and see why millions of viewers are not millions of origin requests.',
      prereqs: ['l0-scaling', 'l1-edge', 'l1-resilience'],
      outcomes: [
        'You can turn “10 million users” into requests per second with stated assumptions.',
        'You can separate read-heavy, write-heavy and contended paths in a design.',
        'You can explain why CDNs make huge audiences cheap and where they stop helping.',
        'You can identify which components scale with users and which stay flat.',
      ],
      sections: [
        C('users-vs-requests', 'Users are not requests',
          `“10 million users” sounds terrifying, but users are not all doing the same thing at the same moment. What matters is <b>how many requests per second</b> hit <b>each component</b>.`,
          `Translate: daily active users → peak concurrent users → actions per user per minute → requests per second per endpoint → requests that reach each tier after caches. Each step needs a stated assumption. The same audience can produce 5,000 req/s on the account service and 50,000 segment fetches per second at the CDN — and only a few hundred per second at the origin.`,
          ['throughput', 'capacity']),
        {
          kind: 'table', title: 'Back-of-the-envelope: a live sports stream (illustrative assumptions)',
          head: ['Quantity', 'Assumption', 'Result'],
          rows: [
            ['Concurrent viewers', 'Given', '10,000,000'],
            ['Segment length', '6 s per video segment (HLS/DASH)', '1 segment request per viewer per 6 s'],
            ['Segment requests at the edge', '10M ÷ 6 s', '≈ 1.7M req/s across the CDN'],
            ['Distinct objects per segment interval', '~6 bitrate renditions × a few audio/subtitle variants', 'tens of distinct objects every 6 s'],
            ['Origin requests', 'Each edge (or mid-tier shield) fetches each object once on a miss; request collapsing merges concurrent misses', 'roughly (edge locations × distinct objects) per 6 s — orders of magnitude below 1.7M req/s'],
            ['Bandwidth at edge', '10M × ~4 Mbit/s average bitrate', '≈ 40 Tbit/s — a CDN-scale problem, not an app-server problem'],
            ['Control-plane API', 'Login, entitlement, manifest refresh — far less frequent', 'thousands to tens of thousands req/s, spiky at match start'],
          ],
        },
        NOTE('assume', 'These numbers are an illustrative estimate with the stated assumptions, not measurements from any company. Always write assumptions next to estimates so others can challenge them.'),
        C('viewers-origin', 'Millions of viewers versus millions of origin requests',
          `Live viewers all want the <b>same</b> few video files at the same time. A [[cdn|CDN]] serves those identical files from caches near viewers, so your servers see each file only a handful of times.`,
          `Origin load ≈ edge requests × (1 − [[cache-hit-ratio|hit ratio]]), and request collapsing plus an origin shield (mid-tier cache) reduce it further. The hard parts become edge bandwidth, cache hit ratio when a new segment appears (everyone misses at once — mitigated by collapsing), and origin/packager resilience. The application API never carries video bytes.`,
          ['cdn', 'origin', 'cache-hit-ratio', 'edge-cache']),
        CMP('cmp-cdn-origin'),
        W('cdn-sim', 'Simulator: scale viewers and break the cache',
          'Scale viewers from 100k to 10M. Change the cache hit ratio and fail an edge region or the origin. Watch origin load and playback errors rather than total viewers.'),
        C('read-write', 'Read paths, write paths and contended paths',
          `Most products are read-heavy: people browse far more than they buy. Reads can be copied and cached; writes to the same record cannot.`,
          `Classify each operation: <b>read-heavy & shareable</b> (catalog, video, schedule) → caches, CDN, read replicas; <b>write-heavy but independent</b> (view events, telemetry) → append-only streams, partitioning; <b>contended writes on few records</b> (last seats, flash-sale stock, a wallet balance) → atomic updates, admission control, queueing. Contended writes do not scale by adding servers — they are limited by how fast one record can be updated correctly.`,
          ['read-replica', 'partitioning', 'lock']),
        C('separate-traffic', 'Separate traffic classes',
          `Video playback, login, payments and comments behave very differently. If they share the same servers and database, a spike in one hurts all.`,
          `Isolate traffic classes into separate services, pools or clusters ([[bulkhead|bulkheads]]): playback via CDN, entitlement via a cache-backed service, payments via a separate, strongly consistent path with its own capacity. Under extreme load, degrade non-essential features (recommendations, live comments) to protect core ones (playback, checkout).`,
          ['bulkhead', 'graceful-degradation']),
        C('capacity-steps', 'Capacity estimation: a repeatable method',
          `Estimates do not need to be exact. They need to be within roughly a factor of two, and they need visible assumptions.`,
          `<ol><li>Peak requests/s per endpoint (daily volume ÷ 86,400 × peak-to-average factor, or concurrent users × actions/min ÷ 60).</li><li>Per-request cost: CPU ms, downstream calls, bytes, tokens.</li><li>Concurrency needed: λ × W ([[little-law|Little’s Law]]).</li><li>Per-replica capacity from load tests, with headroom (run bottlenecks below ~60–70% utilization).</li><li>Shared limits: DB connections, IOPS, LLM TPM/RPM, partition throughput.</li><li>Storage and growth: records/day × size × retention.</li><li>Cost per request at peak and at average.</li></ol>`,
          ['capacity', 'little-law', 'tpm']),
        W('littles-law', 'Calculator: concurrency at peak',
          'Plug in a peak request rate and per-request latency to see in-flight requests — then compare with pool and quota limits.'),
        C('what-scales', 'What scales with users and what stays flat',
          `Some components grow with audience size; others grow with the number of distinct things (videos, products, seats).`,
          `For live streaming, CDN egress scales with viewers, origin load scales with distinct objects × edge locations, and the payment service scales with purchases, not viewers. For a booking system, the waiting room scales with users, but inventory updates are limited by the number of seats and the contention on them. Knowing which axis drives each component tells you where to invest.`,
          ['cdn', 'hot-partition']),
        C('prescale', 'Known peaks: pre-scale, don’t just autoscale',
          `When you know when the spike will come (a match start, a 10:00 Tatkal window, a sale at midnight), get ready before it.`,
          `Reactive [[autoscaling]] lags: metrics must rise, a decision fires, instances start, caches warm. For step changes, pre-provision capacity, pre-warm caches and connection pools, raise quotas with providers in advance, and run load tests that mimic the ramp. Keep autoscaling as a safety net, with sensible maximums.`,
          ['autoscaling', 'cold-start']),
        { kind: 'anatomy', title: 'Anatomy: control plane versus data plane of a streaming platform', caption: 'Video bytes and API calls take different paths. Click to compare.',
          nodes: [
            { id: 'viewer', label: 'Viewers', kind: 'client', col: 0, row: 1, what: 'Millions of players requesting manifests and video segments.' },
            { id: 'cdn', label: 'CDN edges', kind: 'edge', col: 1, row: 0, what: 'Caches video segments near viewers.', scales: 'With viewers (bandwidth).', monitor: 'Hit ratio, edge errors, egress.' },
            { id: 'shield', label: 'Origin shield', kind: 'cache', col: 2, row: 0, what: 'Mid-tier cache that collapses edge misses.', why: 'Protects the origin from many edges missing at once.' },
            { id: 'origin', label: 'Packager / origin', kind: 'storage', col: 3, row: 0, what: 'Produces and stores segments and manifests.', scales: 'With distinct objects, not viewers.', fails: 'If down, new segments stop — live playback stalls everywhere.' },
            { id: 'api', label: 'Control-plane API', kind: 'service', col: 1, row: 2, what: 'Login, entitlement, playback session start.', scales: 'With session starts and refreshes.', fails: 'Spike at match start; degrade non-essential calls.' },
            { id: 'pay', label: 'Payments', kind: 'service', col: 2, row: 2, what: 'Subscriptions and purchases.', why: 'Isolated so streaming load cannot starve it.' },
            { id: 'db', label: 'Account DB', kind: 'db', col: 3, row: 2, what: 'Users, entitlements; cached heavily for reads.' },
          ],
          edges: [['viewer', 'cdn', 'segments'], ['cdn', 'shield', 'miss'], ['shield', 'origin', 'collapsed miss'], ['viewer', 'api', 'session'], ['api', 'db'], ['api', 'pay', 'purchase']] },
      ],
      quiz: [
        { q: 'A live event has 8M concurrent viewers. The CDN reports a 99.5% hit ratio for video segments. What is the most accurate statement about origin load?',
          options: ['The origin must serve 8M requests every few seconds', 'The origin sees about 0.5% of segment requests at most, and request collapsing/shielding reduces that further', 'The origin load is zero', 'The origin load depends only on the API replica count'],
          answer: 1, tag: 'cache-hit-ratio',
          why: 'Origin load ≈ edge requests × miss ratio; shields and collapsing merge concurrent misses for the same object.',
          misconception: { 0: 'That ignores the CDN entirely.', 2: 'New segments must still be fetched once per edge or shield.', 3: 'API replicas do not serve video segments.' } },
        { q: 'During a flash sale, adding API servers does not reduce checkout latency, and database CPU is moderate but lock waits are high on one product row. What is the real constraint?',
          options: ['Network bandwidth', 'Contended writes on a single hot record — limited by how fast that row can be updated correctly', 'Insufficient CDN capacity', 'Too few API replicas'],
          answer: 1, tag: 'lock',
          why: 'Contended writes serialize on the record. The fix is admission control, atomic conditional decrements, or splitting inventory, not more app servers.',
          misconception: { 0: 'Lock waits point to contention, not bandwidth.', 2: 'Checkout writes do not go through the CDN.', 3: 'More replicas increase contention on the same row.' } },
        { q: 'A service gets 43.2M requests per day with a peak-to-average ratio of 5. What is the peak request rate?',
          options: ['500 req/s', '2,500 req/s', '43,200 req/s', '216M req/s'],
          answer: 1, tag: 'capacity',
          why: 'Average = 43.2M ÷ 86,400 = 500 req/s; peak ≈ 5 × 500 = 2,500 req/s.',
          misconception: { 0: 'That is the average, not the peak.', 2: 'That divides by 1,000 instead of seconds per day.', 3: 'That multiplies daily volume by the peak factor without converting to per-second.' } },
        { q: 'Why should payments run on a separate path from playback traffic?',
          options: ['Payments need a CDN', 'Isolation (bulkheads) keeps a playback spike from starving the strongly consistent, lower-volume payment path', 'Payments are read-heavy', 'It reduces video bitrate'],
          answer: 1, tag: 'bulkhead',
          why: 'Different traffic classes have different scaling, consistency and failure needs.',
          misconception: { 0: 'Payments are per-user writes; caching them at the edge is wrong.', 2: 'Payments are write-path, consistency-critical operations.', 3: 'Unrelated.' } },
        { q: 'A match starts at 19:30 and traffic jumps 15× within two minutes. Why is reactive autoscaling alone risky?',
          options: ['Autoscaling cannot add replicas', 'Metrics, scaling decisions, instance start and cache warm-up lag behind a step change, so users hit an under-provisioned system', 'Autoscaling only works for databases', 'It always over-provisions'],
          answer: 1, tag: 'autoscaling',
          why: 'For known step changes, pre-scale and pre-warm; let autoscaling handle the unexpected.',
          misconception: { 0: 'It can add replicas, just not instantly.', 2: 'Autoscaling is mostly used for stateless compute.', 3: 'The risk here is under-provisioning.' } },
      ],
      teachback: { prompt: 'A product manager says “we will have 10 million users, so we need 10 million servers’ worth of capacity.” Explain how you would actually estimate capacity.',
        rubric: 'Users ≠ requests; concurrent users × actions/time → req/s per endpoint; peak factor; CDN hit ratio reduces origin; read vs write vs contended paths; Little’s Law for concurrency; shared limits (DB, quotas); per-replica capacity from load tests with headroom; traffic class isolation; pre-scaling for known peaks; stated assumptions.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-hotstar', 'case-irctc', 'case-blinkit', 'case-flashsale', 'case-netflix-open-connect'], patternRefs: ['p-cdn-edge', 'p-caching', 'p-admission-control', 'p-bulkheads', 'p-capacity-prescaling'],
    },

    /* ---------------------------------------------------------------- L3 */
    {
      id: 'l3-distribution', level: 3, minutes: 30,
      title: 'Load balancing, consistent hashing and service discovery',
      summary: 'How requests find a healthy server: load balancing algorithms, health-based routing, consistent hashing and service discovery.',
      prereqs: ['l2-thinking-at-scale'],
      outcomes: [
        'You can compare round robin, least connections and power-of-two-choices.',
        'You can explain why consistent hashing moves few keys when nodes change.',
        'You can explain how service discovery and health checks keep routing correct.',
        'You can spot when sticky routing helps and when it hurts.',
      ],
      sections: [
        C('lb-algos', 'Load balancing algorithms',
          `A load balancer has to pick a server for each request. Different rules work better for different workloads.`,
          `<ul><li><b>Round robin</b>: rotate through servers. Fine when requests are similar.</li><li><b>Weighted</b>: bigger servers get more.</li><li><b>Least connections / least outstanding requests</b>: send to the least busy server. Much better when request durations vary a lot (LLM calls of 1 s vs 30 s).</li><li><b>Power of two choices</b>: pick two random servers and send to the less loaded one. Close to least-loaded with far less coordination.</li><li><b>Hash-based</b>: hash a key (user, tenant, session) to a server for affinity — see consistent hashing.</li></ul>`,
          ['load-balancer']),
        C('health', 'Health-based routing',
          `A load balancer should only send traffic to servers that can actually handle it.`,
          `Health probes: <b>liveness</b> (is the process alive — restart if not), <b>readiness</b> (should it receive traffic now — e.g. warmed up, dependencies reachable). Passive health checks (outlier detection) eject servers that return errors. A readiness check that tests a shared dependency can remove <i>every</i> server at once when that dependency blips — keep readiness focused on the instance itself.`,
          ['load-balancer', 'failover']),
        C('consistent-hashing', 'Consistent hashing',
          `If you assign keys to servers with “hash(key) mod N”, adding one server reshuffles almost every key. [[consistent-hashing|Consistent hashing]] arranges servers and keys on a ring so adding or removing a server moves only a small fraction of keys.`,
          `Each node owns the arc of the hash ring before it; a key goes to the first node clockwise. Adding a node moves about 1/N of keys. Virtual nodes (many points per physical node) smooth out uneven arcs and let bigger machines take more load. Used in distributed caches, Dynamo-style databases, and sharded services to keep cache hit ratios high during scaling.`,
          ['consistent-hashing', 'sharding']),
        W('consistent-hashing', 'Experiment: add and remove nodes on a hash ring',
          'Add a node and count how many keys move. Compare with modulo hashing. Then add virtual nodes and watch the distribution even out.'),
        C('discovery', 'Service discovery',
          `In a system where servers come and go every minute, callers need a live directory of where each service is running.`,
          `Approaches: DNS-based (a service name resolves to current instances or a virtual IP), registry-based (instances register with a registry; clients or sidecars query it), and platform-provided (Kubernetes Services, Container Apps internal ingress). Discovery must respect health, and caches of discovery results must expire quickly enough to avoid sending traffic to dead instances.`,
          ['service-discovery', 'dns']),
        C('global-lb', 'Global load balancing',
          `Before a request reaches a regional load balancer, something must pick the region: usually the one closest to the user that is healthy.`,
          `Global traffic managers steer users via DNS (return the address of the best region), anycast (the same IP announced from many locations; the network routes to the nearest), or a global L7 proxy such as Azure Front Door that terminates connections at the edge and forwards to healthy origins. DNS-based steering is limited by client caching of records; anycast and edge proxies fail over faster.`,
          ['dns', 'multi-region', 'failover']),
        C('sticky', 'Sticky sessions and affinity',
          `Sometimes it helps to send the same user to the same server — for example to reuse a warm cache. But it makes servers less interchangeable.`,
          `Affinity improves cache locality (and is required for some WebSocket designs) but creates uneven load, breaks when a server dies (state lost) and complicates scale-in. Prefer stateless servers with shared state; if affinity is needed, use consistent hashing so membership changes move few users.`,
          ['stateless', 'consistent-hashing']),
        { kind: 'anatomy', title: 'Anatomy: discovery and balancing inside a cluster', caption: 'Click components.',
          nodes: [
            { id: 'caller', label: 'Chat API', kind: 'service', col: 0, row: 1, what: 'Needs to call the retrieval service.', fails: 'Stale discovery cache sends calls to terminated instances.' },
            { id: 'reg', label: 'Discovery', kind: 'router', col: 1, row: 0, what: 'Current list of healthy instances (DNS, registry or platform service).', fails: 'Registry outage or stale entries.' },
            { id: 'lb', label: 'Client-side LB', kind: 'lb', col: 1, row: 1, what: 'Picks an instance per request (least outstanding / P2C).', why: 'Avoids sending long requests to busy instances.' },
            { id: 'r1', label: 'Retrieval #1', kind: 'service', col: 2, row: 0 },
            { id: 'r2', label: 'Retrieval #2', kind: 'service', col: 2, row: 1 },
            { id: 'r3', label: 'Retrieval #3', kind: 'service', col: 2, row: 2, fails: 'Failing readiness probe removes it from rotation.' },
          ],
          edges: [['caller', 'reg', 'lookup', 'async'], ['caller', 'lb'], ['lb', 'r1'], ['lb', 'r2'], ['lb', 'r3']] },
      ],
      quiz: [
        { q: 'An LLM gateway uses round robin across 10 replicas. Some requests take 1 s and some take 40 s. Several replicas are overloaded while others are idle. Better algorithm?',
          options: ['Random', 'Least outstanding requests (or power-of-two-choices)', 'Round robin with more replicas', 'DNS round robin'],
          answer: 1, tag: 'load-balancer',
          why: 'Variable request duration makes request counts a poor proxy for load; pick the replica with fewer in-flight requests.',
          misconception: { 0: 'Random has the same imbalance problem.', 2: 'Imbalance persists with more replicas.', 3: 'DNS round robin is coarser still and cached by clients.' } },
        { q: 'A cache cluster uses hash(key) mod N. Scaling from 10 to 11 nodes causes a huge spike of misses and database load. Why?',
          options: ['The new node is slow', 'Modulo hashing remaps most keys when N changes; consistent hashing would move only ~1/N', 'Caches must be cleared on scale-out', 'TTL expired everywhere'],
          answer: 1, tag: 'consistent-hashing',
          why: 'Changing N changes the result of mod for most keys, so most lookups go to a node that doesn’t have the data.',
          misconception: { 0: 'Speed does not explain mass misses.', 2: 'They don’t, with consistent hashing.', 3: 'Coincidental expiry would not align with scale-out.' } },
        { q: 'All pods were removed from the load balancer simultaneously when Redis had a 5-second blip. What design error caused it?',
          options: ['Liveness probe too slow', 'The readiness probe checked a shared dependency, so every instance reported unready at once', 'Too many replicas', 'Consistent hashing'],
          answer: 1, tag: 'failover',
          why: 'Readiness should reflect the instance’s own ability to serve. Shared-dependency failures should be handled with degradation, not mass ejection.',
          misconception: { 0: 'Probe speed would not eject all pods together.', 2: 'Replica count does not cause simultaneous ejection.', 3: 'Unrelated.' } },
        { q: 'What do virtual nodes add to consistent hashing?',
          options: ['Encryption', 'Smoother key distribution and weighted capacity per physical node', 'Strong consistency', 'Fewer network hops'],
          answer: 1, tag: 'consistent-hashing',
          why: 'Many ring positions per node average out arc sizes.',
          misconception: { 0: 'Not a security feature.', 2: 'Placement does not define consistency.', 3: 'Hop count is unchanged.' } },
        { q: 'Why can sticky sessions make scale-in painful?',
          options: ['They increase TLS cost', 'Users pinned to a removed server lose local state and are rebalanced unevenly', 'They require WebSockets', 'They disable health checks'],
          answer: 1, tag: 'stateless',
          why: 'Affinity couples users to instances; removing an instance disrupts its users.',
          misconception: { 0: 'TLS cost is unrelated.', 2: 'Stickiness is not limited to WebSockets.', 3: 'Health checks still run.' } },
      ],
      teachback: { prompt: 'Explain how a request from the chat API reaches a healthy retrieval instance, and why consistent hashing matters for caches.',
        rubric: 'Service discovery via DNS/registry/platform; health probes liveness vs readiness; algorithm choice by request variance (least outstanding, P2C); consistent hashing ring moves ~1/N keys; virtual nodes; sticky sessions trade-offs; avoid readiness on shared dependencies.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-dynamo', 'case-chaos-monkey'], patternRefs: ['p-load-balancing', 'p-horizontal-stateless', 'p-index-partition-shard'],
    },

    {
      id: 'l3-replication', level: 3, minutes: 35,
      title: 'Replication, quorums and consistency',
      summary: 'Copies of data for availability and scale: leader-follower, quorums, strong versus eventual consistency, replication lag, and what the CAP theorem does and does not say.',
      prereqs: ['l3-distribution'],
      outcomes: [
        'You can explain synchronous versus asynchronous replication and their failure trade-offs.',
        'You can compute whether a quorum configuration guarantees reading the latest write.',
        'You can describe user-visible symptoms of replication lag and fixes.',
        'You can state CAP precisely and explain its limits (and PACELC).',
      ],
      sections: [
        C('why-replicate', 'Why replicate',
          `[[replication|Replication]] keeps copies of data on several machines so you survive a machine failure and can serve more reads.`,
          `Goals: durability (data survives node loss), availability (keep serving during failures), read scaling (spread reads), and locality (serve users from nearby copies). Every replica must receive every write, so replication helps reads far more than writes.`,
          ['replication', 'read-replica']),
        C('leader-follower', 'Leader-follower replication',
          `One copy (the leader) accepts writes and sends changes to the others (followers). Followers can serve reads.`,
          `<b>Synchronous</b>: the leader waits for follower acknowledgment before confirming the write — no data loss on leader failure, but higher latency and stalls if a follower is slow. <b>Asynchronous</b>: confirm immediately and ship later — fast, but a leader crash can lose recent writes, and followers lag. Semi-synchronous: wait for at least one follower. Failover promotes a follower; you must prevent two leaders (split brain) via fencing or consensus.`,
          ['leader-follower', 'failover', 'replication-lag']),
        C('lag', 'Replication lag',
          `With async replication, followers are a little behind the leader — usually milliseconds, sometimes seconds or minutes under load.`,
          `Symptoms: a user updates their lease note and the refreshed page shows the old value (read-your-writes violation); a list shows an item that its detail page cannot find (monotonic-read violation when bouncing between replicas). Fixes: read your own writes from the leader for a short window, pin a session to one replica, use a replication position/token to wait until the replica has caught up, or read from the leader for critical paths.`,
          ['replication-lag', 'eventual-consistency'],
          `Using a lagging read replica for an inventory check before booking can sell seats that are already gone.`),
        W('replication-lag', 'Experiment: write to the leader, read from a lagging follower',
          'Increase lag and write load. Read immediately after writing and see stale reads. Then enable read-your-writes routing.'),
        C('multi-leaderless', 'Multi-leader and leaderless replication',
          `Some systems accept writes on several nodes, which helps availability and multi-region writes — but then two nodes can accept conflicting writes.`,
          `Multi-leader (common across regions) needs conflict resolution: last-writer-wins (can silently lose updates), merge functions, or CRDTs. Leaderless (Dynamo-style) sends writes and reads to several replicas and uses quorums plus read repair and anti-entropy to converge.`,
          ['replication', 'eventual-consistency']),
        C('quorum', 'Quorums',
          `With N copies, if a write is confirmed by W of them and a read asks R of them, then whenever W + R > N at least one replica in every read has the latest write.`,
          `Example N = 3, W = 2, R = 2: overlap guaranteed. W = 1, R = 1: fast but may read stale data. Quorum overlap alone is not full linearizability (concurrent writes, sloppy quorums and clock-based conflict resolution complicate it), but it is the core intuition behind tunable consistency in Dynamo-style stores like Cassandra.`,
          ['quorum']),
        C('strong-eventual', 'Strong versus eventual consistency',
          `[[strong-consistency|Strong consistency]]: once a write is confirmed, everyone sees it. [[eventual-consistency|Eventual consistency]]: everyone will see it eventually, but not necessarily right away.`,
          `In between are useful guarantees: read-your-writes, monotonic reads, consistent prefix, causal consistency, and bounded staleness. Choose per operation: decisions that cannot be undone (charge, allocate a seat, revoke access) need strong guarantees; displays and analytics usually tolerate staleness.`,
          ['strong-consistency', 'eventual-consistency']),
        CMP('cmp-strong-eventual'),
        C('cap', 'CAP — and its limits',
          `The [[cap-theorem|CAP theorem]] says: when the network splits the system into parts that cannot talk (a partition), each part must either refuse some requests (stay Consistent) or answer with possibly stale data (stay Available).`,
          `CAP is about behavior <b>during partitions</b> only, with specific definitions (linearizability; every non-failed node responds). It does not mean “pick two of three” in normal operation, and real systems choose per operation. PACELC extends it: if Partitioned, choose A or C; Else, choose Latency or Consistency — the trade-off you face every day, even without failures.`,
          ['cap-theorem']),
        { kind: 'anatomy', title: 'Anatomy: leader with two followers', caption: 'Click to see what can go wrong at each copy.',
          nodes: [
            { id: 'app', label: 'App', kind: 'service', col: 0, row: 1 },
            { id: 'leader', label: 'Leader', kind: 'db', col: 1, row: 1, what: 'Accepts all writes; ships the change log to followers.', fails: 'Crash before followers receive recent writes → data loss with async replication.' },
            { id: 'f1', label: 'Follower (sync)', kind: 'db', col: 2, row: 0, what: 'Confirms writes before the leader acknowledges.', fails: 'If slow, every write slows down.' },
            { id: 'f2', label: 'Follower (async)', kind: 'db', col: 2, row: 2, what: 'Receives writes later; serves reads.', fails: 'Replication lag → stale reads.' },
          ],
          edges: [['app', 'leader', 'writes'], ['leader', 'f1', 'sync'], ['leader', 'f2', 'async', 'async'], ['app', 'f2', 'reads']] },
      ],
      quiz: [
        { q: 'A user edits Property A’s lease note, the page reloads, and the old note appears. A second refresh shows the new note. Most likely cause?',
          options: ['Browser cache corruption', 'The write went to the leader and the read hit an asynchronously replicated follower that lagged', 'The database lost the write', 'JWT expiry'],
          answer: 1, tag: 'replication-lag',
          why: 'Classic read-your-writes violation. Route the user’s reads to the leader briefly, or wait for the replica to reach the write’s position.',
          misconception: { 0: 'The second refresh shows the new value without clearing caches.', 2: 'The write appears later, so it was not lost.', 3: 'Auth expiry would cause 401s, not stale data.' } },
        { q: 'N = 5 replicas. Which configuration guarantees read and write quorums overlap?',
          options: ['W = 2, R = 2', 'W = 3, R = 3', 'W = 1, R = 4', 'W = 2, R = 3'],
          answer: 1, tag: 'quorum',
          why: 'W + R > N: 3 + 3 = 6 > 5.',
          misconception: { 0: '2 + 2 = 4 ≤ 5: no guaranteed overlap.', 2: '1 + 4 = 5 is not greater than 5.', 3: '2 + 3 = 5 is not greater than 5.' } },
        { q: 'What does the CAP theorem actually constrain?',
          options: ['All systems can only have two of consistency, availability and partition tolerance at all times', 'Behavior during a network partition: either refuse some requests to stay consistent or serve possibly stale data to stay available', 'Database throughput', 'Whether to use SQL or NoSQL'],
          answer: 1, tag: 'cap-theorem',
          why: 'CAP is about partitions. PACELC adds the latency-versus-consistency trade-off in normal operation.',
          misconception: { 0: 'Partitions are not optional in distributed systems, and the choice applies during them.', 2: 'CAP says nothing about throughput.', 3: 'Both families make different choices, sometimes per operation.' } },
        { q: 'With asynchronous leader-follower replication, what happens if the leader crashes right after acknowledging a write?',
          options: ['Nothing — the write is safe on all replicas', 'The write may be lost if no follower received it before failover', 'Followers reject all future writes', 'The client automatically retries'],
          answer: 1, tag: 'leader-follower',
          why: 'Async acknowledgment precedes replication. Synchronous or semi-synchronous replication narrows this window (RPO).',
          misconception: { 0: 'That describes synchronous replication.', 2: 'A follower is promoted and accepts writes.', 3: 'The client got a success; it has no reason to retry.' } },
        { q: 'For seat allocation, which consistency choice is appropriate?',
          options: ['Eventual consistency everywhere for speed', 'Strong consistency for the reservation decision; eventual consistency acceptable for the availability display', 'No replication', 'Last-writer-wins across regions'],
          answer: 1, tag: 'strong-consistency',
          why: 'Irreversible decisions need strong guarantees; displays can be slightly stale if the final step re-checks atomically.',
          misconception: { 0: 'Stale reads cause overselling.', 2: 'You still need replicas for durability.', 3: 'LWW silently drops one of two conflicting bookings.' } },
      ],
      teachback: { prompt: 'Explain replication lag to a product manager using a lease-editing example, and describe how you would prevent users from seeing their own changes disappear.',
        rubric: 'Leader-follower; async lag; read-your-writes violation; fixes: leader reads after write, session pinning, replication position wait; trade-off latency vs consistency; strong vs eventual per operation; CAP during partitions; quorum W+R>N.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-dynamo', 'case-spanner', 'case-incident-github-2018'], patternRefs: ['p-replication-failover', 'p-consistency-choice'],
    },

    {
      id: 'l3-messaging', level: 3, minutes: 35,
      title: 'Event-driven systems, queues and streams',
      summary: 'Asynchronous communication: message queues versus event streams, Kafka versus Azure Service Bus, delivery guarantees, idempotent consumers and dead-letter queues.',
      prereqs: ['l1-resilience', 'l3-replication'],
      outcomes: [
        'You can distinguish commands from events and queues from streams.',
        'You can explain at-most-once, at-least-once and effectively-once processing.',
        'You can design an idempotent consumer.',
        'You can explain partitions, consumer groups, ordering and dead-letter queues.',
      ],
      sections: [
        C('event-driven', 'Event-driven architecture',
          `Instead of service A calling B, C and D directly, A announces “this happened” and anyone interested reacts. A does not need to know who listens.`,
          `[[event-driven|Event-driven]] systems decouple producers from consumers in time and knowledge. Benefits: independent scaling, new consumers without changing producers, resilience when consumers are down. Costs: eventual consistency, harder debugging (trace IDs in messages), duplicate and out-of-order handling, schema evolution of events.`,
          ['event-driven']),
        C('commands-events', 'Commands versus events',
          `A command says “please do this” (ChargePayment). An event says “this already happened” (PaymentCharged).`,
          `Commands have one intended handler and can be rejected; events are facts with any number of subscribers. Commands fit queues with competing consumers; events fit pub/sub topics or streams. Naming them correctly clarifies ownership and failure handling.`,
          ['message-queue', 'event-stream']),
        C('queue-vs-stream', 'Queues versus streams',
          `A [[message-queue|queue]] is a to-do list: each item is taken by one worker and then removed. An [[event-stream|event stream]] is a logbook: entries stay, and many readers each keep their own bookmark.`,
          `Queues: per-message acknowledgment, locks, retry counts, dead-lettering, competing consumers. Streams: append-only partitions, consumer offsets, retention-based replay, ordering per partition, consumer-group parallelism up to the partition count.`,
          ['message-queue', 'event-stream', 'kafka', 'service-bus']),
        CMP('cmp-kafka-servicebus'),
        C('semantics', 'Delivery semantics',
          `Networks and crashes make it impossible to be sure a message was processed exactly once. You choose which failure you prefer: losing messages, or seeing some twice.`,
          `<ul><li>[[at-most-once|At-most-once]]: acknowledge before processing — a crash loses the message, never duplicates.</li><li>[[at-least-once|At-least-once]]: acknowledge after processing — a crash after processing but before ack causes redelivery (duplicates), never loss. The usual default.</li><li>[[effectively-once|Effectively-once]]: at-least-once delivery + idempotent processing (or transactional offset commits within one system) so duplicates have no extra effect.</li></ul>`,
          ['at-most-once', 'at-least-once', 'effectively-once']),
        W('delivery-semantics', 'Experiment: crash a consumer mid-message',
          'Switch between at-most-once, at-least-once, and at-least-once with an idempotent consumer. Crash the consumer at different points and count lost and duplicated effects.'),
        C('idempotent-consumer', 'Idempotent consumers',
          `Because duplicates will happen, the consumer must make processing a message twice harmless.`,
          `Techniques: store processed message IDs (or business keys) in the same transaction as the side effect, using a unique constraint; make operations naturally idempotent (“set status = PAID” rather than “add ₹500”); use conditional updates with versions. Deduplication windows in brokers (e.g. Service Bus duplicate detection) help producers but do not replace consumer idempotency.`,
          ['idempotent-consumer', 'idempotency']),
        C('ordering', 'Ordering and partitions',
          `Sometimes order matters: “BookingCreated” must be handled before “BookingCancelled” for the same booking.`,
          `Streams guarantee order within a partition; choose a partition key (booking ID) so related events land together. Global ordering does not scale. Queues offer ordering via sessions (Service Bus) keyed by an ID. Retries can reorder messages, so consumers should check versions or sequence numbers.`,
          ['partitioning', 'kafka']),
        C('dlq', 'Poison messages and dead-letter queues',
          `Some messages will always fail — malformed data, a bug. Retrying them forever blocks or wastes the system.`,
          `After a maximum delivery count, move the message to a [[dead-letter-queue|dead-letter queue]] with the failure reason. Alert on DLQ growth, provide tooling to inspect, fix and replay, and never silently discard. In streams, a poison event blocks its partition unless the consumer skips it to a separate error topic.`,
          ['dead-letter-queue']),
        { kind: 'anatomy', title: 'Anatomy: booking events fan out', caption: 'One fact, many independent reactions.',
          nodes: [
            { id: 'booking', label: 'Booking service', kind: 'service', col: 0, row: 1, what: 'Commits the booking and publishes BookingConfirmed.' },
            { id: 'topic', label: 'Event stream', kind: 'stream', col: 1, row: 1, what: 'Partitioned log keyed by booking ID.', fails: 'Hot partition if key is skewed; consumer lag.', monitor: 'Consumer lag per group, throughput per partition.' },
            { id: 'notify', label: 'Notifications', kind: 'worker', col: 2, row: 0, what: 'Sends confirmation email/SMS.', fails: 'Duplicate delivery → duplicate SMS unless idempotent.' },
            { id: 'search', label: 'Search indexer', kind: 'worker', col: 2, row: 1, what: 'Updates availability views.' },
            { id: 'analytics', label: 'Analytics', kind: 'worker', col: 2, row: 2, what: 'Aggregates bookings; can replay from history.' },
            { id: 'dlq', label: 'Dead-letter', kind: 'queue', col: 3, row: 0, what: 'Messages that failed after max attempts.', monitor: 'Alert on growth.' },
          ],
          edges: [['booking', 'topic', 'publish'], ['topic', 'notify', 'group A'], ['topic', 'search', 'group B'], ['topic', 'analytics', 'group C'], ['notify', 'dlq', 'poison', 'async']] },
      ],
      quiz: [
        { q: 'A payment-confirmation consumer occasionally sends two SMS messages for one booking after deployments. Why, and what fixes it?',
          options: ['The broker is buggy; switch brokers', 'At-least-once delivery redelivers messages whose processing finished but was not acknowledged (e.g. during shutdown); record processed IDs atomically with the side effect', 'SMS providers duplicate messages', 'Increase partitions'],
          answer: 1, tag: 'idempotent-consumer',
          why: 'Redelivery after processing is expected with at-least-once. Idempotent consumers make duplicates harmless.',
          misconception: { 0: 'Every broker offering at-least-once behaves this way.', 2: 'The correlation with deployments points at consumer acknowledgment.', 3: 'Partition count does not affect duplicates.' } },
        { q: 'You need analytics, search indexing and notifications to each process every booking event independently, and to rebuild search from history. Best fit?',
          options: ['A single Service Bus queue with competing consumers', 'An event stream (Kafka/Event Hubs) with a consumer group per subscriber and retention for replay', 'Direct synchronous HTTP calls from booking', 'A database trigger that emails'],
          answer: 1, tag: 'event-stream',
          why: 'Streams support independent consumer groups and replay from retained history.',
          misconception: { 0: 'Competing consumers split messages; each subscriber would see only some.', 2: 'Couples booking to every consumer’s availability and latency.', 3: 'Couples business logic to the database and offers no replay.' } },
        { q: 'A consumer acknowledges a message, then crashes before writing to the database. Which semantics is this?',
          options: ['At-least-once', 'At-most-once — the message is lost', 'Exactly-once', 'Effectively-once'],
          answer: 1, tag: 'at-most-once',
          why: 'Ack-before-process can lose messages but never duplicates them.',
          misconception: { 0: 'At-least-once acks after processing.', 2: 'The message was lost, so not exactly-once.', 3: 'Effectively-once requires no loss and idempotent effects.' } },
        { q: 'One malformed message makes a consumer crash repeatedly, and the queue stops draining. What should exist?',
          options: ['Infinite retries', 'A max delivery count that moves the message to a dead-letter queue with alerting', 'Deleting the queue', 'More consumers'],
          answer: 1, tag: 'dead-letter-queue',
          why: 'DLQs isolate poison messages so healthy traffic continues, while preserving them for inspection.',
          misconception: { 0: 'Infinite retries keep blocking.', 2: 'Loses all messages.', 3: 'Every consumer will crash on the same message.' } },
        { q: 'Events for the same booking are processed out of order. Which change helps most?',
          options: ['Use the booking ID as the partition (or session) key so its events stay ordered, and check version numbers in the consumer', 'Use random partition keys', 'Increase retention', 'Use at-most-once delivery'],
          answer: 0, tag: 'partitioning',
          why: 'Ordering is per partition/session; version checks handle the remaining reordering from retries.',
          misconception: { 1: 'Random keys scatter related events across partitions.', 2: 'Retention does not affect order.', 3: 'Losing messages is not a fix for ordering.' } },
      ],
      teachback: { prompt: 'Explain to a teammate why “exactly-once delivery” is the wrong goal and what you build instead.',
        rubric: 'Failures make ack timing ambiguous; at-most-once vs at-least-once; at-least-once default; effectively-once = at-least-once + idempotent consumer (processed IDs in same transaction, natural idempotency, conditional updates); ordering per partition/session; DLQ for poison messages; trace IDs in messages.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-kafka-cdc-outbox', 'case-payments-idempotency'], patternRefs: ['p-event-driven', 'p-queue-leveling', 'p-idempotency', 'p-outbox-cdc'],
    },

    {
      id: 'l3-transactions', level: 3, minutes: 35,
      title: 'Sagas, the outbox pattern and CQRS',
      summary: 'Keep data consistent across services without one big transaction: two-phase commit and its limits, sagas with compensation, the transactional outbox, CDC, CQRS and event sourcing.',
      prereqs: ['l3-messaging'],
      outcomes: [
        'You can explain why distributed transactions (2PC) are avoided in most microservice designs.',
        'You can design a saga with compensating steps for a booking-and-payment flow.',
        'You can explain the dual-write problem and how the outbox pattern solves it.',
        'You can explain when CQRS and event sourcing are worth their complexity.',
      ],
      sections: [
        C('problem', 'The problem: one action, many databases',
          `Booking a train seat might touch inventory, payments and notifications — each owned by a different service with its own database. There is no single transaction that covers them all.`,
          `Local ACID [[transaction|transactions]] stop at a database boundary. Across services you must choose between coordinated commit protocols (2PC) and designs that accept temporary inconsistency but guarantee eventual correctness (sagas).`,
          ['transaction', 'saga']),
        C('2pc', 'Two-phase commit and why it is rarely used across services',
          `[[two-phase-commit|Two-phase commit]] asks every participant “can you commit?”, then tells everyone “commit” only if all said yes.`,
          `Problems: the coordinator is a blocking point (participants holding locks wait if it dies between phases), latency of extra round trips, reduced availability (any participant down blocks everyone), and limited support across heterogeneous services and brokers. It is used inside some databases and tightly coupled systems; across independent services, sagas are the norm.`,
          ['two-phase-commit']),
        C('saga', 'Sagas',
          `A [[saga]] breaks a big action into steps, each a local transaction. If a later step fails, earlier steps are undone by <b>compensating</b> actions.`,
          `Orchestration: a coordinator (a workflow engine or service) tells each participant what to do and handles failures — explicit and easier to monitor. Choreography: services react to each other’s events — less central coupling but harder to follow. Compensations are semantic undos (refund, release seat), not rollbacks; intermediate states are visible to other readers, so model them explicitly (e.g. HELD, PAYMENT_PENDING).`,
          ['saga', 'event-driven']),
        {
          kind: 'steps', title: 'Saga: book a seat and take payment (orchestrated)',
          steps: [
            { title: 'Hold the seat', text: 'Inventory service atomically moves one seat from AVAILABLE to HELD with an expiry (e.g. 10 minutes). Local transaction.' },
            { title: 'Create the booking', text: 'Booking record in PAYMENT_PENDING with an idempotency key.' },
            { title: 'Charge payment', text: 'Payment service charges with the same idempotency key so retries cannot double-charge.' },
            { title: 'Confirm', text: 'On success: seat HELD → BOOKED, booking → CONFIRMED, event published.' },
            { title: 'Compensate on failure', text: 'Payment declined or timed out beyond the deadline: release the seat (HELD → AVAILABLE), mark booking FAILED, refund if a charge was captured.' },
            { title: 'Expire abandoned holds', text: 'A sweeper releases holds whose expiry passed — so crashed sagas cannot strand inventory.' },
          ],
        },
        C('dual-write', 'The dual-write problem',
          `A service saves a booking to its database and then publishes “BookingConfirmed” to a broker. If it crashes between those two steps, the database and the rest of the world disagree.`,
          `Writing to two systems without a shared transaction can leave either one missing. Reversing the order has the same problem (event published, DB write fails). Retrying the publish without care causes duplicates. This is one of the most common hidden bugs in event-driven systems.`,
          ['outbox-pattern', 'event-driven']),
        C('outbox', 'The transactional outbox',
          `Instead of publishing directly, write the event into an “outbox” table <b>in the same database transaction</b> as the business change. A separate relay reads the outbox and publishes.`,
          `Because both rows commit together, the event exists if and only if the change exists. The relay (polling or [[cdc|change data capture]] reading the database log) publishes with at-least-once semantics, so consumers must be idempotent. The outbox decouples business transactions from broker availability.`,
          ['outbox-pattern', 'cdc', 'idempotent-consumer']),
        W('delivery-semantics', 'Experiment: crashes and duplicates in event publishing',
          'Use the delivery simulator to see why at-least-once publishing from an outbox requires idempotent consumers.'),
        C('cqrs', 'CQRS',
          `[[cqrs|CQRS]] (Command Query Responsibility Segregation) uses one model for writes and separate, optimized models for reads.`,
          `Writes go to a normalized, consistent store; events or CDC update read models shaped for queries (a search index, a denormalized dashboard table, a vector index). Benefit: each side scales and is optimized independently. Cost: read models are eventually consistent and you operate more stores and pipelines. Use it when read and write needs genuinely diverge, not by default.`,
          ['cqrs', 'denormalization', 'eventual-consistency']),
        C('event-sourcing', 'Event sourcing',
          `Instead of storing the current state, store every change as an event and compute state by replaying them — like a bank ledger instead of just a balance.`,
          `[[event-sourcing|Event sourcing]] provides a full audit history, temporal queries, and the ability to rebuild read models. Costs: event schema evolution, snapshotting for performance, harder ad-hoc queries, and GDPR-style deletion challenges. Often combined with CQRS. Valuable in domains that are naturally ledgers (payments, inventory movements); overkill for simple CRUD.`,
          ['event-sourcing', 'cqrs']),
        { kind: 'anatomy', title: 'Anatomy: outbox with CDC', caption: 'The business change and the event commit atomically.',
          nodes: [
            { id: 'svc', label: 'Booking service', kind: 'service', col: 0, row: 1, what: 'Writes booking row and outbox row in one transaction.' },
            { id: 'db', label: 'Booking DB', kind: 'db', sub: 'bookings + outbox', col: 1, row: 1, what: 'Holds the state and the pending events.', fails: 'Outbox table grows if relay stalls — monitor age.' },
            { id: 'cdc', label: 'CDC relay', kind: 'worker', col: 2, row: 1, what: 'Reads committed outbox rows (via log) and publishes them.', fails: 'Publishes duplicates after restarts — at-least-once.' },
            { id: 'bus', label: 'Event stream', kind: 'stream', col: 3, row: 1 },
            { id: 'read', label: 'Read model', kind: 'search', col: 4, row: 0, what: 'Denormalized query view (CQRS).', fails: 'Eventually consistent; lag visible to users.' },
            { id: 'pay', label: 'Payment saga', kind: 'service', col: 4, row: 2, what: 'Reacts to events; compensates on failure.' },
          ],
          edges: [['svc', 'db', '1 txn'], ['db', 'cdc', 'log'], ['cdc', 'bus', 'publish'], ['bus', 'read', 'project'], ['bus', 'pay', 'react']] },
      ],
      quiz: [
        { q: 'A service commits an order and then publishes OrderPlaced. After a crash, some orders never trigger fulfilment. What pattern fixes this?',
          options: ['Publish first, then commit', 'Transactional outbox: write the event to an outbox table in the same transaction, relay it afterwards', 'Two separate retries', 'Increase broker partitions'],
          answer: 1, tag: 'outbox-pattern',
          why: 'Atomic commit of state and event removes the dual-write gap; the relay delivers at-least-once.',
          misconception: { 0: 'Then a failed commit leaves an event for an order that does not exist.', 2: 'Retries do not help if the process crashed between steps.', 3: 'Partitions do not address atomicity.' } },
        { q: 'In a booking saga, payment fails after the seat was held. What should happen?',
          options: ['Roll back the inventory database transaction from 2 minutes ago', 'Run a compensating action that releases the hold (HELD → AVAILABLE) and marks the booking failed', 'Leave the seat held forever', 'Retry payment indefinitely'],
          answer: 1, tag: 'saga',
          why: 'Earlier local transactions already committed; sagas undo them semantically with compensations.',
          misconception: { 0: 'Committed transactions cannot be rolled back later.', 2: 'Strands inventory; holds need expiry and release.', 3: 'Unbounded retries block the user and resources.' } },
        { q: 'Why is two-phase commit usually avoided across microservices?',
          options: ['It is not consistent', 'It blocks participants holding locks if the coordinator fails, adds latency, and reduces availability', 'It requires NoSQL', 'It is illegal'],
          answer: 1, tag: 'two-phase-commit',
          why: '2PC trades availability and latency for atomicity; across independent services that trade is usually bad.',
          misconception: { 0: '2PC gives atomic commit when it completes.', 2: 'It is common in relational systems.', 3: 'Not a legal matter.' } },
        { q: 'When is CQRS a good choice?',
          options: ['For every CRUD app', 'When read patterns differ greatly from write patterns (e.g. search and dashboards over a transactional core) and slight read staleness is acceptable', 'When you need strong consistency on every read', 'To avoid using a database'],
          answer: 1, tag: 'cqrs',
          why: 'CQRS separates models when needs diverge; it introduces eventual consistency and more moving parts.',
          misconception: { 0: 'Adds complexity with little benefit for simple CRUD.', 2: 'Read models are typically eventually consistent.', 3: 'It uses more stores, not fewer.' } },
        { q: 'An outbox relay restarts and republishes the last 50 events. What must be true for this to be safe?',
          options: ['Consumers are idempotent', 'The broker deletes duplicates forever', 'Events have no IDs', 'The relay uses at-most-once'],
          answer: 0, tag: 'idempotent-consumer',
          why: 'Outbox relays are at-least-once; consumers must tolerate duplicates.',
          misconception: { 1: 'Broker deduplication is time-windowed and does not cover all cases.', 2: 'IDs are what make deduplication possible.', 3: 'At-most-once would lose events.' } },
      ],
      teachback: { prompt: 'Design the consistency mechanism for “hold seat → charge payment → confirm booking → send ticket” across three services.',
        rubric: 'No 2PC; orchestrated saga with explicit states; atomic seat hold with expiry; idempotency keys for payment; compensations (release seat, refund); outbox for events; CDC relay; idempotent consumers; sweeper for expired holds; visible intermediate states.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-kafka-cdc-outbox', 'case-irctc', 'case-payments-idempotency'], patternRefs: ['p-saga', 'p-outbox-cdc', 'p-cqrs-es', 'p-idempotency'],
    },

    {
      id: 'l3-fault-tolerance', level: 3, minutes: 35,
      title: 'Fault tolerance, retry storms and disaster recovery',
      summary: 'Contain failures with bulkheads and circuit breakers, avoid retry storms, and plan recovery across zones and regions with explicit RTO and RPO.',
      prereqs: ['l3-replication', 'l1-resilience'],
      outcomes: [
        'You can explain how a slow dependency cascades into a full outage.',
        'You can design bulkheads that contain the blast radius of a failure.',
        'You can explain retry storms and how retry budgets stop them.',
        'You can choose a DR strategy from RTO and RPO targets.',
      ],
      sections: [
        C('cascade', 'Cascading failures',
          `One slow service makes its callers wait; their threads fill up; their callers wait on them; soon everything is down — even services that had nothing wrong with them.`,
          `Cascades spread through shared resource pools, synchronous call chains, and retries. Ingredients: no timeouts, shared thread/connection pools across dependencies, retries at every layer, and health checks that pass while the service is useless. Breaking the chain requires timeouts, isolation, fail-fast and load shedding.`,
          ['retry-storm', 'bulkhead', 'circuit-breaker']),
        C('bulkheads', 'Bulkheads',
          `Ships have watertight compartments so one hole doesn’t sink the ship. A [[bulkhead]] gives each dependency or tenant its own limited pool of resources.`,
          `Examples: separate connection pools or concurrency limits per downstream (the reranker can use at most 30 slots, so it can’t consume all 200 workers); separate deployments for interactive versus batch traffic; separate LLM deployments per priority tier; cell-based architectures where each cell serves a subset of customers. Cost: some capacity is reserved and may sit idle.`,
          ['bulkhead']),
        C('breakers-again', 'Circuit breakers at system scale',
          `A breaker per dependency stops a sick service from dragging callers down and gives it room to recover.`,
          `Combine breakers with fallbacks (cached answer, degraded feature) and with bulkheads. Trip on slow calls as well as errors, because “slow but alive” is the most damaging state. Expose breaker state as a metric.`,
          ['circuit-breaker', 'graceful-degradation']),
        C('retry-storm', 'Retry storms',
          `When a service struggles, every caller retries — multiplying traffic exactly when the service can least handle it. A brief blip becomes a long outage.`,
          `Amplification grows with retries per layer and number of layers. Prevent with: retry budgets (e.g. retries may add at most 10% extra load), single-layer retries, exponential backoff with jitter, circuit breakers, honoring Retry-After, and server-side load shedding that rejects early and cheaply. A [[retry-storm]] is often what keeps a system down after the original cause has passed (a metastable failure).`,
          ['retry-storm', 'jitter', 'load-shedding']),
        W('retry-jitter', 'Experiment: watch a retry storm keep a service down',
          'Fail the dependency briefly. With aggressive retries the load stays above capacity even after it recovers. Add backoff, jitter and a budget and watch it recover.'),
        C('dlq-ft', 'Dead letters and partial failure',
          `Not every failure should block the system. Isolate the bad item and keep going.`,
          `Dead-letter queues isolate poison messages; per-tenant queues isolate noisy tenants; timeouts and partial results let an aggregate request return what it has (e.g. compare Property A and B, with B’s rates marked unavailable).`,
          ['dead-letter-queue', 'graceful-degradation']),
        C('rto-rpo', 'RTO and RPO',
          `Two questions define disaster recovery: how long can we be down ([[rto|RTO]], recovery time objective), and how much recent data can we lose ([[rpo|RPO]], recovery point objective)?`,
          `RPO is driven by replication mode: synchronous replication can give near-zero RPO within a region; asynchronous cross-region replication gives an RPO of seconds to minutes; backups give hours. RTO is driven by automation: hot standby fails over in seconds to minutes; restoring from backup takes hours. Lower targets cost more — choose per service by business impact.`,
          ['rto', 'rpo', 'failover']),
        {
          kind: 'table', title: 'Disaster recovery strategies',
          head: ['Strategy', 'How it works', 'Typical RTO', 'Typical RPO', 'Cost'],
          rows: [
            ['Backup & restore', 'Restore data and redeploy in another region', 'Hours', 'Hours (last backup)', 'Low'],
            ['Pilot light', 'Data replicated; minimal core infrastructure running', 'Tens of minutes', 'Minutes', 'Low–medium'],
            ['Warm standby', 'Scaled-down full copy running; scale up on failover', 'Minutes', 'Seconds–minutes', 'Medium'],
            ['Active-active', 'Multiple regions serve traffic simultaneously', 'Near zero (reroute)', 'Near zero to seconds, depending on replication', 'High; hardest data consistency'],
          ],
        },
        C('multi-region', 'Multi-region architecture',
          `Running in two or more regions protects against a whole region going down — but data has to be in both places.`,
          `Stateless tiers replicate easily; data is the hard part. Options: active-passive with async replication (simple, possible data loss and manual or automated failover), or active-active with partitioned ownership (each record has a home region) or multi-region databases with conflict resolution or consensus (higher write latency). Global routing (DNS/Front Door) directs users and fails over. Test failover regularly — untested DR plans fail.`,
          ['multi-region', 'failover', 'replication-lag']),
        C('fault-detection', 'Detecting failure',
          `You can’t recover from a failure you haven’t noticed — and false alarms cause their own damage.`,
          `Use health probes, heartbeats with timeouts, and outlier detection. Detection is a trade-off: aggressive timeouts give fast failover but cause flapping and split-brain risks on slow networks; conservative timeouts lengthen outages. Pair automated failover with fencing so the old leader cannot keep writing.`,
          ['failover', 'leader-follower']),
        { kind: 'anatomy', title: 'Anatomy: bulkheaded chatbot dependencies', caption: 'Each dependency has its own limited pool; a sick reranker cannot take down chat.',
          nodes: [
            { id: 'api', label: 'Chat API', kind: 'service', col: 0, row: 1, what: '200 worker slots in total.' },
            { id: 'p1', label: 'Pool: search', kind: 'security', kindLabel: 'Bulkhead', sub: '60 slots', col: 1, row: 0, what: 'Concurrency limit for retrieval calls.' },
            { id: 'p2', label: 'Pool: reranker', kind: 'security', kindLabel: 'Bulkhead', sub: '30 slots + breaker', col: 1, row: 1, what: 'Isolated limit with circuit breaker and fallback to un-reranked results.' },
            { id: 'p3', label: 'Pool: LLM', kind: 'security', kindLabel: 'Bulkhead', sub: '100 slots', col: 1, row: 2, what: 'Bounded by LLM quota.' },
            { id: 'search', label: 'AI Search', kind: 'search', col: 2, row: 0 },
            { id: 'rr', label: 'Reranker', kind: 'service', col: 2, row: 1, fails: 'Becomes slow — breaker opens, chat continues without reranking.' },
            { id: 'llm', label: 'Azure OpenAI', kind: 'llm', col: 2, row: 2 },
          ],
          edges: [['api', 'p1'], ['api', 'p2'], ['api', 'p3'], ['p1', 'search'], ['p2', 'rr'], ['p3', 'llm']] },
      ],
      quiz: [
        { q: 'A recommendation service becomes slow (not down). Minutes later the checkout API is also failing, although it only calls recommendations for an optional widget. What design flaw allowed this?',
          options: ['Checkout needed more CPU', 'Checkout shared its worker/connection pool with the optional recommendation call and had no tight timeout or breaker', 'The database was undersized', 'Recommendations should be in the same process'],
          answer: 1, tag: 'bulkhead',
          why: 'Without isolation, threads waiting on the slow optional dependency starve the critical path. Bulkhead it, time it out, and degrade.',
          misconception: { 0: 'Waiting threads do not use CPU.', 2: 'The trigger was the slow recommendation service.', 3: 'Co-location removes the network hop but not the coupling of resources.' } },
        { q: 'A dependency recovered 10 minutes ago, but traffic to it is still 4× normal and it keeps failing. What is happening?',
          options: ['A DDoS attack', 'A retry storm: accumulated retries keep load above capacity (a metastable failure)', 'DNS caching', 'Replication lag'],
          answer: 1, tag: 'retry-storm',
          why: 'Retries sustain the overload after the original trigger is gone. Shed load, open breakers, use retry budgets with jitter.',
          misconception: { 0: 'Possible in general, but the timing tied to a failure points to self-inflicted retries.', 2: 'DNS does not multiply traffic.', 3: 'Lag affects data freshness, not request volume.' } },
        { q: 'The business can tolerate losing at most 5 seconds of booking data in a regional disaster and being down at most 15 minutes. Which target pair is this?',
          options: ['RTO 5 s, RPO 15 min', 'RPO 5 s, RTO 15 min', 'RTO = RPO = 5 s', 'SLO 99.9%'],
          answer: 1, tag: 'rpo',
          why: 'RPO is acceptable data loss; RTO is acceptable downtime.',
          misconception: { 0: 'Swapped definitions.', 2: 'Downtime tolerance is 15 minutes, not 5 s.', 3: 'An SLO is a different concept.' } },
        { q: 'What is the hardest part of active-active multi-region?',
          options: ['Deploying stateless containers twice', 'Handling writes to the same data in two regions: conflicts, replication lag or cross-region consensus latency', 'Buying a second domain name', 'Configuring TLS'],
          answer: 1, tag: 'multi-region',
          why: 'Data consistency across regions forces a choice between latency, conflicts, and partitioned ownership.',
          misconception: { 0: 'Stateless tiers are the easy part.', 2: 'Trivial.', 3: 'Routine.' } },
        { q: 'Which retry policy best avoids storms?',
          options: ['Retry every layer 5 times immediately', 'Retry once or twice at a single layer with exponential backoff, jitter, a retry budget and a circuit breaker', 'Never time out', 'Retry only on 400 errors'],
          answer: 1, tag: 'retry',
          why: 'Bounded, desynchronized retries at one layer with a budget limit amplification.',
          misconception: { 0: 'Multiplies load massively.', 2: 'Hangs consume resources and cause cascades.', 3: '400s are client errors that will fail again.' } },
      ],
      teachback: { prompt: 'Explain to an incident reviewer how a slow reranker could take down an entire chatbot, and the mechanisms that would have contained it.',
        rubric: 'Slow-not-dead dependency; threads/pools shared; cascade; timeouts; bulkheads per dependency; circuit breaker on slow calls; fallback to un-reranked results (graceful degradation); retry budgets/jitter to avoid storms; load shedding; monitoring of breaker state and pool saturation; RTO/RPO context for bigger failures.' },
      interviewRefs: [], scenarioRefs: [], caseRefs: ['case-chaos-monkey', 'case-incident-aws-2021', 'case-incident-github-2018', 'case-sre-error-budgets'], patternRefs: ['p-bulkheads', 'p-circuit-breaker-retries', 'p-graceful-degradation', 'p-multi-region', 'p-replication-failover', 'p-chaos-engineering'],
    },
  ]);
})();
